import fs from 'fs';
import path from 'path';

const ARTIFACTS_DIR = 'C:/Users/Admin/.gemini/antigravity-ide/brain/d284d670-0cfd-4f12-bbed-f8eeaea36551';
const TEMPMEDIA_DIR = path.join(ARTIFACTS_DIR, '.tempmediaStorage');

async function run() {
  const tabsRes = await fetch('http://127.0.0.1:9222/json');
  const tabs = await tabsRes.json();
  const pageTab = tabs.find(t => t.id === 'D4361F184EE470F9E6FE2DB8E04A64BA') || tabs.find(t => t.type === 'page');

  const ws = new WebSocket(pageTab.webSocketDebuggerUrl);
  let id = 1;
  const pending = new Map();

  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const msgId = id++;
      pending.set(msgId, { resolve, reject });
      ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  }

  ws.onmessage = (event) => {
    const data = JSON.parse(event.data);
    if (data.id && pending.has(data.id)) {
      const { resolve, reject } = pending.get(data.id);
      pending.delete(data.id);
      if (data.error) reject(data.error);
      else resolve(data.result);
    }
  };

  ws.onopen = async () => {
    try {
      await send('Page.enable');
      await send('Emulation.setDeviceMetricsOverride', {
        width: 1440,
        height: 900,
        deviceScaleFactor: 1,
        mobile: false
      });
      // Navigate to live store URL
      await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=product-v2' });
      await new Promise(r => setTimeout(r, 3000));

      // Check if password page or storefront
      const pageInfo = await send('Runtime.evaluate', {
        expression: 'JSON.stringify({ title: document.title, url: window.location.href, hasBuyBox: !!document.getElementById("zvBuyBox") })'
      });
      console.log('Live Page Info:', pageInfo.result.value);

      const shot = await send('Page.captureScreenshot', { format: 'png' });
      const shotPath = path.join(TEMPMEDIA_DIR, `live_theme_pdp_${Date.now()}.png`);
      fs.writeFileSync(shotPath, Buffer.from(shot.data, 'base64'));
      console.log('Live Theme Screenshot saved:', shotPath);

      ws.close();
      process.exit(0);
    } catch (e) {
      console.error(e);
      ws.close();
      process.exit(1);
    }
  };
}

run();

