/* Fixture Upright Columns (Structural Beams on Store Walls - Warm Champagne Bronze) */
.zv-fixture-column {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 22px;
  background: linear-gradient(90deg, #D4C3B7 0%, #EFE8E2 50%, #C7B5A8 100%);
