  border-left: 1px solid rgba(255, 255, 255, 0.65);
  box-shadow: 4px 0 16px rgba(43, 27, 36, 0.06);
  pointer-events: none;
  z-index: 2;
}

.zv-fixture-left { left: 16px; }
.zv-fixture-right { right: 16px; }

