const fs = require('fs');
const zlib = require('zlib');

function encodePng(width, height, rgbaBuffer) {
  const signature = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);

  // IHDR
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // color type RGBA
  ihdr[10] = 0; // compression
  ihdr[11] = 0; // filter
  ihdr[12] = 0; // interlace

  function makeChunk(type, data) {
    const len = data.length;
    const buf = Buffer.alloc(12 + len);
    buf.writeUInt32BE(len, 0);
    buf.write(type, 4, 4, 'ascii');
    data.copy(buf, 8);
    // CRC32
    const crc = crc32(buf.slice(4, 8 + len));
    buf.writeInt32BE(crc, 8 + len);
    return buf;
  }

  // Simple CRC32 implementation
  const crcTable = [];
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    crcTable[n] = c;
  }
  function crc32(buf) {
    let crc = -1;
    for (let i = 0; i < buf.length; i++) {
      crc = (crc >>> 8) ^ crcTable[(crc ^ buf[i]) & 0xFF];
    }
    return (crc ^ -1);
  }

  const ihdrChunk = makeChunk('IHDR', ihdr);

  // Scanlines with filter byte 0
  const stride = 1 + width * 4;
  const rawData = Buffer.alloc(height * stride);
  for (let y = 0; y < height; y++) {
    rawData[y * stride] = 0; // Filter None
    rgbaBuffer.copy(rawData, y * stride + 1, y * width * 4, (y + 1) * width * 4);
  }

  const compressed = zlib.deflateSync(rawData);
  const idatChunk = makeChunk('IDAT', compressed);
  const iendChunk = makeChunk('IEND', Buffer.alloc(0));

  return Buffer.concat([signature, ihdrChunk, idatChunk, iendChunk]);
}

// Read original
const buf = fs.readFileSync('assets/infrared-battle-set-cutout.png');
let pos = 8;
const idatChunks = [];
while (pos < buf.length) {
  const len = buf.readUInt32BE(pos);
  const type = buf.toString('ascii', pos + 4, pos + 8);
  if (type === 'IDAT') idatChunks.push(buf.slice(pos + 8, pos + 8 + len));
  pos += 12 + len;
}
const compressed = Buffer.concat(idatChunks);
const uncompressed = zlib.inflateSync(compressed);

const origW = 1280, origH = 960;
const origStride = 1 + origW * 4;

// Bounding box from previous inspection:
// minX: 35, maxX: 1236, minY: 131, maxY: 888
const minX = 35, maxX = 1236, minY = 131, maxY = 888;
const newW = maxX - minX + 1;
const newH = maxY - minY + 1;

const croppedRgba = Buffer.alloc(newW * newH * 4);
for (let y = 0; y < newH; y++) {
  const srcY = minY + y;
  const srcRow = srcY * origStride + 1 + minX * 4;
  const dstRow = y * newW * 4;
  uncompressed.copy(croppedRgba, dstRow, srcRow, srcRow + newW * 4);
}

const newPng = encodePng(newW, newH, croppedRgba);
fs.writeFileSync('assets/infrared-battle-set-cutout.png', newPng);
console.log('Successfully trimmed PNG to', newW, 'x', newH, 'Bytes:', newPng.length);
