args.Content:
const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
  '--headless=new',
  '--remote-debugging-port=9223',
  '--window-size=1200,900',
  'http://127.0.0.1:9292/collections/all?view=showroom'
]);

setTimeout(() => {
  http.get('http://127.0.0.1:9223/json', (res) => {
    let raw = '';
    res.on('data', c => raw += c);
    res.on('end', () => {
      try {
        const list = JSON.parse(raw);
        const page = list.find(p => p.type === 'page');
        if (!page) {
          console.log('No page found');
          chromeProc.kill();
          return;
        }

        // Use built-in node WebSocket if available or client
        let ws;
        try {
          ws = new WebSocket(page.webSocketDebuggerUrl);
        } catch(e) {
          console.log('Global WebSocket not found, testing via fetch');
          chromeProc.kill();
          return;
        }
        let id = 1;
        function send(method, params = {}) {
          const reqId = id++;
          ws.send(JSON.stringify({ id: reqId, method, params }));
          return reqId;
        }

        ws.onopen = () => {
          send('Runtime.enable');
          send('Page.enable');

          setTimeout(() => {
            send('Runtime.evaluate', {
              expression: 'document.querySelector(".zv-shelf-clip-tag").click()'
            });

            setTimeout(() => {
              send('Page.captureScreenshot');
            }, 700);
          }, 1500);
        };

        ws.onmessage = (event) => {
          const res = JSON.parse(event.data);
          if (res.result && res.result.data) {
            fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\scratch\\qa_click_modal.png', Buffer.from(res.result.data, 'base64'));
            console.log('Saved qa_click_modal.png successfully');
            ws.close();
            chromeProc.kill();
          }
        };
      } catch (e) {
        console.log('Error:', e.message);
        chromeProc.kill();
      }
    });
  }).on('error', (e) => {
    console.log('HTTP err:', e.message);
    chromeProc.kill();
  });
}, 2000);

