const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
  '--headless=new',
  '--remote-debugging-port=9224',
  '--window-size=390,844',
  'http://127.0.0.1:9292/collections/all?view=showroom'
]);

setTimeout(() => {
  http.get('http://127.0.0.1:9224/json', (res) => {
    let raw = '';
    res.on('data', c => raw += c);
    res.on('end', () => {
      try {
        const list = JSON.parse(raw);
        const page = list.find(p => p.type === 'page');
        if (!page) {
          chromeProc.kill();
          return;
        }

        const ws = new WebSocket(page.webSocketDebuggerUrl);
        let id = 1;
        function send(method, params = {}) {
          const reqId = id++;
          ws.send(JSON.stringify({ id: reqId, method, params }));
          return reqId;
        }

        ws.onopen = () => {
          send('Runtime.enable');
          send('Page.enable');

          setTimeout(() => {
            send('Runtime.evaluate', {
              expression: 'document.querySelector(".zv-shelf-clip-tag").click()'
            });

            setTimeout(() => {
              send('Page.captureScreenshot');
            }, 700);
          }, 1500);
        };

        ws.onmessage = (event) => {
          const res = JSON.parse(event.data);
          if (res.result && res.result.data) {
            fs.writeFileSync('C:\\Users\\Admin\\.gemini\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\scratch\\qa_click_mobile_sheet.png', Buffer.from(res.result.data, 'base64'));
            console.log('Saved qa_click_mobile_sheet.png successfully');
            ws.close();
            chromeProc.kill();
          }
        };
      } catch (e) {
        console.log('Error:', e.message);
        chromeProc.kill();
      }
    });
  }).on('error', (e) => {
    console.log('HTTP err:', e.message);
    chromeProc.kill();
  });
}, 2000);

