const fs = require('fs');
const http = require('http');

const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
  '--headless=new',
  '--remote-debugging-port=9225',
  '--window-size=1200,900',
  'https://ikwh1h-fx.myshopify.com/password'
]);

setTimeout(() => {
  http.get('http://127.0.0.1:9225/json', (res) => {
    let raw = '';
    res.on('data', c => raw += c);
    res.on('end', () => {
      try {
        const list = JSON.parse(raw);
        const page = list.find(p => p.type === 'page');
        if (!page) {
          chromeProc.kill();
          return;
        }

        const ws = new WebSocket(page.webSocketDebuggerUrl);
        let id = 1;
        function send(method, params = {}) {
          const reqId = id++;
          ws.send(JSON.stringify({ id: reqId, method, params }));
          return reqId;
        }

        ws.onopen = () => {
          send('Runtime.enable');
          send('Page.enable');

          // Submit storefront password
          setTimeout(() => {
            send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector('input[type="password"]');
                const form = document.querySelector('form');
                if (input && form) {
                  input.value = '[STOREFRONT_PASSWORD_REDACTED]';
                  form.submit();
                }
              `
            });

            // Wait for password submit and navigate to showroom
            setTimeout(() => {
              send('Page.navigate', {
                url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom'
              });

              setTimeout(() => {
                send('Page.captureScreenshot');
              }, 2500);
            }, 1500);
          }, 1000);
        };

        ws.onmessage = (event) => {
          const res = JSON.parse(event.data);
          if (res.result && res.result.data) {
            fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\scratch\\qa_live_desktop.png', Buffer.from(res.result.data, 'base64'));
            console.log('Saved qa_live_desktop.png successfully');
            ws.close();
            chromeProc.kill();
          }
        };
      } catch (e) {
        console.log('Error:', e.message);
        chromeProc.kill();
      }
    });
  }).on('error', e => {
    console.log('HTTP err:', e.message);
    chromeProc.kill();
  });
}, 2000);

