args.Content:
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();

  await page.goto('https://ikwh1h-fx.myshopify.com/password', { waitUntil: 'networkidle' });
  await page.fill('input[type="password"]', '[STOREFRONT_PASSWORD_REDACTED]');
  await Promise.all([
    page.waitForNavigation({ waitUntil: 'networkidle' }),
    page.press('input[type="password"]', 'Enter')
  ]);

  // Desktop Homepage
  await page.screenshot({ path: 'qa_homepage_desktop_current.png', fullPage: false });
  console.log('Homepage desktop captured: qa_homepage_desktop_current.png');

  // Scroll down and capture more sections
  await page.evaluate(() => window.scrollBy(0, 800));
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'qa_homepage_desktop_mid.png', fullPage: false });

  // Footer capture
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'qa_homepage_desktop_footer.png', fullPage: false });

  // Mobile View
  await page.setViewportSize({ width: 390, height: 844 });
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'qa_homepage_mobile_current.png', fullPage: false });
  console.log('Homepage mobile captured: qa_homepage_mobile_current.png');

  // Showroom View
  await page.goto('https://ikwh1h-fx.myshopify.com/collections/all?view=showroom', { waitUntil: 'networkidle' });
  await page.screenshot({ path: 'qa_showroom_mobile_current.png', fullPage: false });

  await page.setViewportSize({ width: 1440, height: 900 });
  await page.screenshot({ path: 'qa_showroom_desktop_current.png', fullPage: false });
  console.log('Showroom captured');

  await browser.close();
})();

