async function publish() {
  const mutation = `
    mutation productPublish($id: ID!) {
      productPublish(input: { id: $id }) {
        product {
          id
          status
        }
        userErrors {
          field
          message
        }
      }
      productUpdate(input: { id: $id, status: ACTIVE }) {
        product {
          id
          status
        }
        userErrors {
          field
          message
        }
      }
    }
  `;
  const res = await adminGraphql(mutation, { id: 'gid://shopify/Product/15635841057139' });
  console.log(JSON.stringify(res, null, 2));
}

publish().catch(console.error);

