const { spawn } = require('child_process');
const fs = require('fs');
const http = require('http');

async function capture() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9227',
    '--window-size=1440,900',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  await new Promise(r => setTimeout(r, 2000));

  http.get('http://127.0.0.1:9227/json', (res) => {
    let raw = '';
    res.on('data', c => raw += c);
    res.on('end', () => {
      const list = JSON.parse(raw);
      const page = list.find(p => p.type === 'page');
      if (!page) {
        console.error('No page found');
        chromeProc.kill();
        return;
      }

      const ws = new WebSocket(page.webSocketDebuggerUrl);
      let id = 1;
      function send(method, params = {}) {
        return new Promise((resolve) => {
          const reqId = id++;
          function handleMsg(evt) {
            const data = JSON.parse(evt.data);
            if (data.id === reqId) {
              ws.removeEventListener('message', handleMsg);
              resolve(data);
            }
          }
          ws.addEventListener('message', handleMsg);
          ws.send(JSON.stringify({ id: reqId, method, params }));
        });
      }

      ws.onopen = async () => {
        await send('Runtime.enable');
        await send('Page.enable');

        // Submit storefront password
        await send('Runtime.evaluate', {
          expression: `
            const input = document.querySelector('input[type="password"]');
            const form = document.querySelector('form');
            if (input && form) {
              input.value = '[STOREFRONT_PASSWORD_REDACTED]';
              form.submit();
            }
          `
        });

        await new Promise(r => setTimeout(r, 2000));

        // 1. Desktop Homepage with preview_theme_id
        console.log('Navigating to Desktop Homepage...');
        await send('Page.navigate', {
          url: 'https://ikwh1h-fx.myshopify.com/?preview_theme_id=197111906675'
        });
        await new Promise(r => setTimeout(r, 3000));

        let res = await send('Page.captureScreenshot');
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_home_desktop.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_home_desktop.png');

        // Scroll to footer and capture
        await send('Runtime.evaluate', { expression: 'window.scrollTo(0, document.body.scrollHeight)' });
        await new Promise(r => setTimeout(r, 1000));
        res = await send('Page.captureScreenshot');
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_footer_desktop.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_footer_desktop.png');

        // 2. Desktop Showroom Shelf
        console.log('Navigating to Desktop Showroom Shelf...');
        await send('Page.navigate', {
          url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom&preview_theme_id=197111906675'
        });
        await new Promise(r => setTimeout(r, 3500));
        res = await send('Page.captureScreenshot');
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_showroom_desktop.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_showroom_desktop.png');

        // 3. Mobile View (390x844)
        console.log('Setting Mobile Viewport...');
        await send('Emulation.setDeviceMetricsOverride', {
          width: 390,
          height: 844,
          deviceScaleFactor: 2,
          mobile: true
        });

        // Mobile Showroom Shelf
        await new Promise(r => setTimeout(r, 1000));
        res = await send('Page.captureScreenshot');
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_showroom_mobile.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_showroom_mobile.png');

        // Mobile Homepage
        console.log('Navigating to Mobile Homepage...');
        await send('Page.navigate', {
          url: 'https://ikwh1h-fx.myshopify.com/?preview_theme_id=197111906675'
        });
        await new Promise(r => setTimeout(r, 3000));
        res = await send('Page.captureScreenshot');
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_home_mobile.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_home_mobile.png');

        // Open Mobile Drawer and capture
        await send('Runtime.evaluate', { expression: 'toggleWillaDrawer()' });
        await new Promise(r => setTimeout(r, 800));
        res = await send('Page.captureScreenshot');
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_drawer_mobile.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_drawer_mobile.png');

        ws.close();
        chromeProc.kill();
        console.log('QA captures completed successfully!');
        process.exit(0);
      };
    });
  });
}

capture().catch(err => {
  console.error(err);
  process.exit(1);
});

