      if (!page) {
        chromeProc.kill();
        return;
      }

      const ws = new WebSocket(page.webSocketDebuggerUrl);
      let id = 1;
      function send(method, params = {}) {
        return new Promise((resolve) => {
          const reqId = id++;
          function handleMsg(evt) {
            const data = JSON.parse(evt.data);
            if (data.id === reqId) {
              ws.removeEventListener('message', handleMsg);
              resolve(data);
            }
          }
          ws.addEventListener('message', handleMsg);
          ws.send(JSON.stringify({ id: reqId, method, params }));
        });
      }

      ws.onopen = async () => {
        await send('Runtime.enable');
        await send('Page.enable');

        await send('Runtime.evaluate', {
          expression: `
            const input = document.querySelector('input[type="password"]');
            const form = document.querySelector('form');
            if (input && form) {
              input.value = '[STOREFRONT_PASSWORD_REDACTED]';
              form.submit();
            }
          `
        });

        await new Promise(r => setTimeout(r, 2000));

        await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/' });
        await new Promise(r => setTimeout(r, 3000));

        // Capture full page
        let res = await send('Page.captureScreenshot', { captureBeyondViewport: true });
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_homepage_fullpage.png', Buffer.from(res.result.data, 'base64'));
