const { spawn } = require('child_process');
const fs = require('fs');
const http = require('http');

async function fullPageCapture() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9235',
    '--window-size=1440,2400',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  await new Promise(r => setTimeout(r, 2000));

  http.get('http://127.0.0.1:9235/json', (res) => {
    let raw = '';
    res.on('data', c => raw += c);
    res.on('end', () => {
      const list = JSON.parse(raw);
      const page = list.find(p => p.type === 'page');
      if (!page) {
        chromeProc.kill();
        return;
      }

      const ws = new WebSocket(page.webSocketDebuggerUrl);
      let id = 1;
      function send(method, params = {}) {
        return new Promise((resolve) => {
          const reqId = id++;
          function handleMsg(evt) {
            const data = JSON.parse(evt.data);
            if (data.id === reqId) {
              ws.removeEventListener('message', handleMsg);
              resolve(data);
            }
          }
          ws.addEventListener('message', handleMsg);
          ws.send(JSON.stringify({ id: reqId, method, params }));
        });
      }

      ws.onopen = async () => {
        await send('Runtime.enable');
        await send('Page.enable');

        await send('Runtime.evaluate', {
          expression: `
            const input = document.querySelector('input[type="password"]');
            const form = document.querySelector('form');
            if (input && form) {
              input.value = '[STOREFRONT_PASSWORD_REDACTED]';
              form.submit();
            }
          `
        });

        await new Promise(r => setTimeout(r, 2000));

        // Desktop Preview Homepage
        await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/?preview_theme_id=197111906675' });
        await new Promise(r => setTimeout(r, 3000));

        // Capture full desktop page
        let res = await send('Page.captureScreenshot', { captureBeyondViewport: true });
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_homepage_v2.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_homepage_v2.png');

        // Mobile View
        await send('Emulation.setDeviceMetricsOverride', {
          width: 390,
          height: 844,
          deviceScaleFactor: 2,
          mobile: true
        });
        await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/?preview_theme_id=197111906675' });
        await new Promise(r => setTimeout(r, 3000));

        res = await send('Page.captureScreenshot', { captureBeyondViewport: true });
        fs.writeFileSync('C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_dev_homepage_mobile_v2.png', Buffer.from(res.result.data, 'base64'));
        console.log('Saved qa_dev_homepage_mobile_v2.png');

        ws.close();
        chromeProc.kill();
        process.exit(0);
      };
    });
  });
}

