const { spawn } = require('child_process');
const http = require('http');

async function testMobileClick() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9225',
    '--window-size=390,844',
    'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9225/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) {
            console.log('No page found');
            chromeProc.kill();
            return;
          }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data.result);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            // Check if password page is showing
            const passCheck = await send('Runtime.evaluate', {
              expression: 'Boolean(document.querySelector("#password, input[name=\'password\']"))'
            });

            if (passCheck.result && passCheck.result.value) {
              console.log('Password page detected, submitting password...');
              await send('Runtime.evaluate', {
                expression: `
                  const input = document.querySelector("#password, input[name='password']");
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                `
              });
              await new Promise(r => setTimeout(r, 3000));
              await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom' });
              await new Promise(r => setTimeout(r, 3000));
            }

            const currentUrl = await send('Runtime.evaluate', {
              expression: 'window.location.href'
            });
            console.log('Current URL after load:', currentUrl.result.value);

            // Check both links in DOM
            const inspectLinkInfo = await send('Runtime.evaluate', {
              expression: `
                const l1 = document.querySelector('#zvInspectPdpLink');
                const l2 = document.querySelector('#zvMobileSheetPdpLink');
                JSON.stringify({
                  inspectHref: l1 ? l1.href : 'none',
                  inspectText: l1 ? l1.innerText : 'none',
                  mobileHref: l2 ? l2.href : 'none',
                  mobileText: l2 ? l2.innerText : 'none',
                  windowWidth: window.innerWidth
                });
              `
            });
            console.log('Links before click:', inspectLinkInfo.result.value);

            // Now click the shelf tag or shelf item
            console.log('Clicking .zv-shelf-clip-tag...');
            await send('Runtime.evaluate', {
              expression: 'document.querySelector(".zv-shelf-clip-tag").click()'
            });
            await new Promise(r => setTimeout(r, 1000));

            const inspectLinkAfterClick = await send('Runtime.evaluate', {
              expression: `
                const l1 = document.querySelector('#zvInspectPdpLink');
                const l2 = document.querySelector('#zvMobileSheetPdpLink');
                JSON.stringify({
                  inspectHref: l1 ? l1.href : 'none',
                  mobileHref: l2 ? l2.href : 'none',
                  mobileSheetActive: document.querySelector('#zvMobileSheetOverlay') ? document.querySelector('#zvMobileSheetOverlay').classList.contains('active') : false,
                  desktopBayActive: document.querySelector('#zvSpatialInspectBay') ? document.querySelector('#zvSpatialInspectBay').classList.contains('active') : false
                });
              `
            });
            console.log('Links after opening modal/sheet:', inspectLinkAfterClick.result.value);

            // Now click the PDP link (test both or whichever is visible)
            const clickRes = await send('Runtime.evaluate', {
              expression: `
                const l1 = document.querySelector('#zvInspectPdpLink');
                const l2 = document.querySelector('#zvMobileSheetPdpLink');
                if (l2 && document.querySelector('#zvMobileSheetOverlay').classList.contains('active')) {
                  l2.click();
                  'clicked_mobile_link: ' + l2.href;
                } else if (l1) {
                  l1.click();
                  'clicked_inspect_link: ' + l1.href;
                } else {
                  'no link clicked';
                }
              `
            });
            console.log('Click result:', clickRes.result.value);

            await new Promise(r => setTimeout(r, 3000));

            const finalUrl = await send('Runtime.evaluate', {
              expression: 'window.location.href'
            });
            console.log('Final URL after clicking link:', finalUrl.result.value);

            ws.close();
            chromeProc.kill();
          };
        } catch (e) {
          console.error('Error:', e);
          chromeProc.kill();
        }
      });
    }).on('error', (e) => {
      console.error('HTTP err:', e);
      chromeProc.kill();
    });
  }, 2000);
}

testMobileClick();

