const { spawn } = require('child_process');
const http = require('http');

async function testMobileClickDev() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9227',
    '--window-size=390,844',
    'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom&preview_theme_id=197111906675'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9227/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) {
            console.log('No page found');
            chromeProc.kill();
            return;
          }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            const passCheck = await send('Runtime.evaluate', {
              expression: 'Boolean(document.querySelector("#password, input[name=\'password\']"))'
            });

            if (passCheck.result && passCheck.result.result && passCheck.result.result.value) {
              await send('Runtime.evaluate', {
                expression: `
                  const input = document.querySelector("#password, input[name='password']");
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                `
              });
              await new Promise(r => setTimeout(r, 2500));
              await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom&preview_theme_id=197111906675' });
              await new Promise(r => setTimeout(r, 2500));
            }

            console.log('1. Checking initial link elements in DOM...');
            const initLinks = await send('Runtime.evaluate', {
              expression: `
                const l1 = document.querySelector('#zvInspectPdpLink');
                const l2 = document.querySelector('#zvMobileSheetPdpLink');
                JSON.stringify({
                  l1Href: l1 ? l1.href : null,
                  l1Text: l1 ? l1.innerText.trim() : null,
                  l2Href: l2 ? l2.href : null,
                  l2Text: l2 ? l2.innerText.trim() : null
                });
              `
            });
            console.log('Initial Links:', initLinks.result.result.value);

            console.log('2. Clicking shelf item to open mobile sheet...');
            await send('Runtime.evaluate', {
              expression: 'document.querySelector(".zv-shelf-item").click()'
            });
            await new Promise(r => setTimeout(r, 1000));

            const sheetStatus = await send('Runtime.evaluate', {
              expression: `
                const l2 = document.querySelector('#zvMobileSheetPdpLink');
                const overlay = document.querySelector('#zvMobileSheetOverlay');
                JSON.stringify({
                  overlayActive: overlay ? overlay.classList.contains('active') : false,
                  l2Href: l2 ? l2.href : null,
                  l2Text: l2 ? l2.innerText.trim() : null
                });
              `
            });
            console.log('Sheet status after click:', sheetStatus.result.result.value);

            console.log('3. Clicking the PDP link inside mobile sheet (#zvMobileSheetPdpLink)...');
            await send('Runtime.evaluate', {
              expression: 'document.querySelector("#zvMobileSheetPdpLink").click()'
            });

            await new Promise(r => setTimeout(r, 3500));

            const finalUrl = await send('Runtime.evaluate', {
              expression: 'window.location.href'
            });
            console.log('>>> FINAL URL AFTER CLICKING PDP LINK:', finalUrl.result.result.value);

            ws.close();
            chromeProc.kill();
          };
        } catch (e) {
          console.error('Error:', e);
          chromeProc.kill();
        }
      });
    }).on('error', (e) => {
      console.error('HTTP err:', e);
      chromeProc.kill();
    });
  }, 2000);
}

testMobileClickDev();

const { spawn } = require('child_process');
