                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');
            await send('Network.enable');

            ws.addEventListener('message', (e) => {
              const msg = JSON.parse(e.data);
              if (msg.method === 'Network.responseReceived') {
                const resp = msg.params.response;
                if (resp.status >= 300 && resp.status < 400) {
                  console.log('Redirect:', resp.status, resp.url, '->', resp.headers['location'] || resp.headers['Location']);
                }
              }
            });

            const passCheck = await send('Runtime.evaluate', {
              expression: 'Boolean(document.querySelector("#password, input[name=\'password\']"))'
            });

            if (passCheck.result && passCheck.result.result && passCheck.result.result.value) {
              await send('Runtime.evaluate', {
                expression: `
                  const input = document.querySelector("#password, input[name='password']");
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                `
              });
              await new Promise(r => setTimeout(r, 2500));
              await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector' });
              await new Promise(r => setTimeout(r, 3000));
            }

            const currentUrl = await send('Runtime.evaluate', {
              expression: 'window.location.href'
            });
            console.log('Current URL after direct navigation:', currentUrl.result.result.value);

            const pageTitle = await send('Runtime.evaluate', {
              expression: 'document.title'
            });
            console.log('Page title:', pageTitle.result.result.value);

            const hasPdpMain = await send('Runtime.evaluate', {
              expression: 'Boolean(document.querySelector(".zv-pdp-v2, .product-form, #AddToCart, .zavelyn-v4-pdp-main"))'
            });
            console.log('Has PDP Main DOM element:', hasPdpMain.result.result.value);

            ws.close();
            chromeProc.kill();
          };
        } catch (e) {
          console.error('Error:', e);
          chromeProc.kill();
        }
      });
    }).on('error', (e) => {
      console.error('HTTP err:', e);
      chromeProc.kill();
    });
  }, 2000);
}

testDirectPDP();

