const { spawn } = require('child_process');
const http = require('http');

async function testPDPResponse() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9229',
    '--window-size=1200,800',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9229/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) {
            chromeProc.kill();
            return;
          }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');
            await send('Network.enable');

            ws.addEventListener('message', (e) => {
              const msg = JSON.parse(e.data);
              if (msg.method === 'Network.responseReceived') {
                const r = msg.params.response;
                if (r.url.includes('kids-infrared') || r.status >= 300) {
                  console.log('Network Response:', r.status, r.statusText, r.url, 'Location:', r.headers['location'] || r.headers['Location']);
                }
              }
            });

            // Submit password
            console.log('Entering password...');
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });

            // Wait for password submission to complete
            await new Promise(r => setTimeout(r, 4000));

            const curUrl1 = await send('Runtime.evaluate', { expression: 'window.location.href' });
            console.log('URL after login:', curUrl1.result.result.value);

            // Now navigate to PDP
            console.log('Navigating to PDP...');
            await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector' });

            await new Promise(r => setTimeout(r, 4000));

            const curUrl2 = await send('Runtime.evaluate', { expression: 'window.location.href' });
            console.log('URL after navigating to PDP:', curUrl2.result.result.value);

            const title = await send('Runtime.evaluate', { expression: 'document.title' });
            console.log('Document title:', title.result.result.value);

            const bodySnippet = await send('Runtime.evaluate', {
              expression: 'document.body ? document.body.innerText.substring(0, 300) : "no body"'
            });
            console.log('Body snippet:\n', bodySnippet.result.result.value);

            ws.close();
            chromeProc.kill();
          };
        } catch(e) {
          console.error(e);
          chromeProc.kill();
        }
      });
    }).on('error', (e) => {
      console.error(e);
      chromeProc.kill();
    });
  }, 2000);
}

testPDPResponse();

