const { spawn } = require('child_process');
const http = require('http');

async function testColProduct() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9230',
    '--window-size=1200,800',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9230/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');
            await send('Network.enable');

            ws.addEventListener('message', (e) => {
              const msg = JSON.parse(e.data);
              if (msg.method === 'Network.responseReceived') {
                const r = msg.params.response;
                if (r.url.includes('kids-infrared') || r.status >= 300) {
                  console.log('Network Response:', r.status, r.statusText, r.url);
                }
              }
            });

            // Submit password
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });

            await new Promise(r => setTimeout(r, 3500));

            console.log('Navigating to collection product URL...');
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/collections/interactive-toys/products/kids-infrared-battle-blaster-set-with-target-projector'
            });

            await new Promise(r => setTimeout(r, 4000));

            const curUrl = await send('Runtime.evaluate', { expression: 'window.location.href' });
            console.log('Current URL:', curUrl.result.result.value);

            const title = await send('Runtime.evaluate', { expression: 'document.title' });
            console.log('Document title:', title.result.result.value);

            ws.close();
            chromeProc.kill();
          };
        } catch(e) {
          console.error(e);
          chromeProc.kill();
        }
      });
    }).on('error', (e) => {
      console.error(e);
      chromeProc.kill();
    });
  }, 2000);
}

testColProduct();

