const { spawn } = require('child_process');
const http = require('http');

async function testViewProductV2() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9231',
    '--window-size=1200,800',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9231/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');
            await send('Network.enable');

            ws.addEventListener('message', (e) => {
              const msg = JSON.parse(e.data);
              if (msg.method === 'Network.responseReceived') {
                const r = msg.params.response;
                if (r.status >= 300) {
                  console.log('Redirect:', r.status, r.url, '->', r.headers['location'] || r.headers['Location']);
                }
              }
            });

            // Submit password
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });

            await new Promise(r => setTimeout(r, 3500));

            console.log('1. Testing /collections/interactive-toys?view=product-v2 ...');
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/collections/interactive-toys?view=product-v2'
            });

            await new Promise(r => setTimeout(r, 4000));

            const curUrl = await send('Runtime.evaluate', { expression: 'window.location.href' });
            console.log('Result URL 1:', curUrl.result.result.value);

            const hasPdpMain = await send('Runtime.evaluate', {
              expression: 'Boolean(document.querySelector(".zv-pdp-v2, .zavelyn-v4-pdp-main, #AddToCart"))'
            });
            console.log('Has PDP Main in interactive-toys?view=product-v2:', hasPdpMain.result.result.value);

            console.log('2. Testing /collections/all?view=product-v2 ...');
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=product-v2'
            });

            await new Promise(r => setTimeout(r, 4000));
            const curUrl2 = await send('Runtime.evaluate', { expression: 'window.location.href' });
            console.log('Result URL 2:', curUrl2.result.result.value);

            ws.close();
            chromeProc.kill();
          };
        } catch(e) {
          console.error(e);
          chromeProc.kill();
        }
      });
    }).on('error', (e) => {
      console.error(e);
      chromeProc.kill();
    });
  }, 2000);
}

testViewProductV2();

