import { adminGraphql } from './config.mjs';

async function updatePricing() {
  const mutation = `
    mutation productVariantsBulkUpdate($productId: ID!, $variants: [ProductVariantsBulkInput!]!) {
      productVariantsBulkUpdate(productId: $productId, variants: $variants) {
        productVariants {
          id
          title
          price
          compareAtPrice
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const res = await adminGraphql(mutation, {
    productId: "gid://shopify/Product/15635841057139",
    variants: [
      {
        id: "gid://shopify/ProductVariant/67297621934451",
        price: "129.00",
        compareAtPrice: "258.00"
      },
      {
        id: "gid://shopify/ProductVariant/67297622131059",
        price: "245.10",
        compareAtPrice: "516.00"
      },
      {
        id: "gid://shopify/ProductVariant/67297622163827",
        price: "328.95",
        compareAtPrice: "774.00"
      }
    ]
  });

  console.log('Update result:', JSON.stringify(res, null, 2));
}

updatePricing().catch(console.error);

