const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

async function capturePDP() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9234',
    '--window-size=1200,900',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9234/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            // Password
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });

            await new Promise(r => setTimeout(r, 3500));

            // Navigate to PDP preview
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=product-v2&preview_theme_id=197111513459'
            });

            await new Promise(r => setTimeout(r, 4000));

            const shot = await send('Page.captureScreenshot');
            if (shot.result && shot.result.data) {
              fs.writeFileSync(
                'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_ads_ready_pdp_desktop.png',
                Buffer.from(shot.result.data, 'base64')
              );
              console.log('Saved qa_ads_ready_pdp_desktop.png');
            }

            // Scroll down to how it works / setup section
            await send('Runtime.evaluate', {
              expression: `
                const hiw = document.querySelector("#tmHowItWorks");
                if (hiw) hiw.scrollIntoView();
              `
            });
            await new Promise(r => setTimeout(r, 1200));

            const shot2 = await send('Page.captureScreenshot');
            if (shot2.result && shot2.result.data) {
              fs.writeFileSync(
                'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_ads_ready_pdp_setup.png',
                Buffer.from(shot2.result.data, 'base64')
              );
              console.log('Saved qa_ads_ready_pdp_setup.png');
            }

            ws.close();
            chromeProc.kill();
          };
        } catch(e) {
          console.error(e);
          chromeProc.kill();
        }
      });
    }).on('error', (e) => {
      console.error(e);
      chromeProc.kill();
    });
  }, 2000);
}

capturePDP();

