const https = require('https');

function loginAndFetch(url) {
  const postData = 'form_type=storefront_password&password=[STOREFRONT_PASSWORD_REDACTED]';
  const req = https.request('https://ikwh1h-fx.myshopify.com/password', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Content-Length': postData.length
    }
  }, (res) => {
    const cookie = res.headers['set-cookie'];
    const cookieHeader = cookie ? cookie.map(c => c.split(';')[0]).join('; ') : '';

    https.get(url, {
      headers: { 'Cookie': cookieHeader }
    }, (res2) => {
      let body = '';
      res2.on('data', chunk => body += chunk);
      res2.on('end', () => {
        console.log('Fetched:', url);
        console.log('Status:', res2.statusCode);
        console.log('Specialized Stores present:', body.includes('Walk Into Our Specialized Stores'));
        console.log('Interactive Toys present:', body.includes('Interactive Toys'));
        console.log('2.5D Showroom present:', body.includes('2.5D Showroom'));
        console.log('Flash sale marquee present:', body.includes('FLASH SALE'));

        // Find all section IDs or classes
        const matches = body.match(/id="shopify-section-[^"]+"/g);
        console.log('Shopify sections on page:', matches);

        // Check announcement bar
        const ann = body.match(/<div[^>]*class="[^"]*announcement[^"]*"[^>]*>[\s\S]*?<\/div>/gi);
        if (ann) {
          console.log('Announcement snippet:', ann[0].slice(0, 300));
        }
      });
    });
  });
  req.write(postData);
  req.end();
}

loginAndFetch('https://ikwh1h-fx.myshopify.com/');
loginAndFetch('https://ikwh1h-fx.myshopify.com/collections/all?view=showroom');

