async function checkAndPublish() {
  const prodRes = await adminGraphql(`
    query {
      product(id: "gid://shopify/Product/15635841057139") {
        id
        title
        status
        publishedAt
        resourcePublicationsV2(first: 10) {
          edges {
            node {
              publication {
                id
                name
              }
              isPublished
              publishDate
            }
          }
        }
      }
      publications(first: 10) {
        edges {
          node {
            id
            name
          }
        }
      }
    }
  `);

  console.log('Product Info:', JSON.stringify(prodRes.product, null, 2));
  console.log('Available Publications:', JSON.stringify(prodRes.publications, null, 2));

  // If not published to Online Store, publish it!
  const onlineStorePub = prodRes.publications.edges.find(e => e.node.name.toLowerCase().includes('online store'));
  if (onlineStorePub) {
    console.log(`Publishing product to Online Store (${onlineStorePub.node.id})...`);
    const pubRes = await adminGraphql(`
      mutation publishablePublish($id: ID!, $input: [PublicationInput!]!) {
        publishablePublish(id: $id, input: $input) {
          publishable {
            availablePublicationsCount {
              count
            }
          }
          userErrors {
            field
            message
          }
        }
      }
    `, {
      id: "gid://shopify/Product/15635841057139",
      input: [
        {
          publicationId: onlineStorePub.node.id
        }
      ]
    });
    console.log('Publish result:', JSON.stringify(pubRes, null, 2));
  }
}

checkAndPublish().catch(console.error);

