import { adminGraphql } from './config.mjs';

async function publish() {
  const query = `
    query {
      publications(first: 10) {
        edges {
          node {
            id
            name
          }
        }
      }
    }
  `;
  const pubList = await adminGraphql(query);
  console.log('Publications:', JSON.stringify(pubList, null, 2));

  const onlineStore = pubList.publications.edges.find(e => 
    e.node.name.toLowerCase().includes('online store')
  );

  if (!onlineStore) {
    console.error('Online store publication not found!');
    return;
  }

  console.log('Publishing to:', onlineStore.node.name, onlineStore.node.id);

  const mutation = `
    mutation publishablePublish($id: ID!, $input: [PublicationInput!]!) {
      publishablePublish(id: $id, input: $input) {
        publishable {
          availablePublicationsCount {
            count
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;
  const res = await adminGraphql(mutation, {
    id: 'gid://shopify/Product/15635841057139',
    input: [
      {
        publicationId: onlineStore.node.id
      }
    ]
  });
  console.log('Result:', JSON.stringify(res, null, 2));
}

publish().catch(console.error);

