const { spawn } = require('child_process');
const http = require('http');

async function testPDP() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9247',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9247/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            // Enter password
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });

            await new Promise(r => setTimeout(r, 2000));

            // Navigate to product page
            console.log('Navigating to product page...');
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector'
            });

            await new Promise(r => setTimeout(r, 3000));

            const curUrl = await send('Runtime.evaluate', {
              expression: 'window.location.href'
            });
            console.log('Current URL after navigation:', curUrl.result ? curUrl.result.result.value : 'none');

            const title = await send('Runtime.evaluate', {
              expression: 'document.title'
            });
            console.log('Document title:', title.result ? title.result.result.value : 'none');

            const h1 = await send('Runtime.evaluate', {
              expression: 'document.querySelector("h1") ? document.querySelector("h1").innerText : "no h1"'
            });
            console.log('H1:', h1.result ? h1.result.result.value : 'none');

            chromeProc.kill();
            process.exit(0);
          };
        } catch (err) {
          console.error(err);
          chromeProc.kill();
          process.exit(1);
        }
      });
    });
  }, 1500);
}

testPDP();

