const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');
const path = require('path');

const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551';

async function runQA() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9249',
    '--window-size=1280,900',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9249/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            // 1. Enter storefront password
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });
            await new Promise(r => setTimeout(r, 2000));

            // 2. Capture Showroom Shelf (Desktop)
            console.log('Capturing Showroom Desktop...');
            await send('Emulation.setDeviceMetricsOverride', {
              width: 1280,
              height: 850,
              deviceScaleFactor: 1,
              mobile: false
            });
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom&preview_theme_id=197111513459'
            });
            await new Promise(r => setTimeout(r, 3500));

            const shelfShot = await send('Page.captureScreenshot', { format: 'png' });
            if (shelfShot && shelfShot.result && shelfShot.result.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_showroom_shelf_centered_desktop.png'), Buffer.from(shelfShot.result.data, 'base64'));
              console.log('Saved qa_showroom_shelf_centered_desktop.png');
            }

            // 3. Capture Showroom Shelf (Mobile 390px)
            console.log('Capturing Showroom Mobile...');
            await send('Emulation.setDeviceMetricsOverride', {
              width: 390,
              height: 844,
              deviceScaleFactor: 2,
              mobile: true
            });
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/collections/all?view=showroom&preview_theme_id=197111513459'
            });
            await new Promise(r => setTimeout(r, 3500));

            const shelfMobileShot = await send('Page.captureScreenshot', { format: 'png' });
            if (shelfMobileShot && shelfMobileShot.result && shelfMobileShot.result.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_showroom_shelf_centered_mobile.png'), Buffer.from(shelfMobileShot.result.data, 'base64'));
              console.log('Saved qa_showroom_shelf_centered_mobile.png');
            }

            // 4. Capture Homepage Top / Announcement Bar
            console.log('Capturing Homepage Header & Announcement...');
            await send('Emulation.setDeviceMetricsOverride', {
              width: 1280,
              height: 900,
              deviceScaleFactor: 1,
              mobile: false
            });
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/?preview_theme_id=197111513459'
            });
            await new Promise(r => setTimeout(r, 3000));

            const homeShot = await send('Page.captureScreenshot', { format: 'png' });
            if (homeShot && homeShot.result && homeShot.result.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_homepage_clean_desktop.png'), Buffer.from(homeShot.result.data, 'base64'));
              console.log('Saved qa_homepage_clean_desktop.png');
            }

            chromeProc.kill();
            process.exit(0);
          };
        } catch (e) {
          console.error(e);
          chromeProc.kill();
          process.exit(1);
        }
      });
    });
  }, 1500);
}

runQA();

const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

async function removeBgInChrome() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9251',
    '--window-size=1000,1000',
    'about:blank'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9251/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        const list = JSON.parse(raw);
        const page = list.find(p => p.type === 'page');
        const ws = new WebSocket(page.webSocketDebuggerUrl);
        let id = 1;
        function send(method, params = {}) {
          return new Promise((resolve) => {
            const reqId = id++;
            const handler = (event) => {
              const data = JSON.parse(event.data);
              if (data.id === reqId) {
                ws.removeEventListener('message', handler);
                resolve(data);
              }
            };
            ws.addEventListener('message', handler);
            ws.send(JSON.stringify({ id: reqId, method, params }));
          });
        }

        ws.onopen = async () => {
          await send('Runtime.enable');

          const result = await send('Runtime.evaluate', {
            awaitPromise: true,
            expression: `
              new Promise((resolve) => {
                const img = new Image();
                img.crossOrigin = 'anonymous';
                img.onload = () => {
                  const canvas = document.createElement('canvas');
                  canvas.width = img.width;
                  canvas.height = img.height;
                  const ctx = canvas.getContext('2d');
                  ctx.drawImage(img, 0, 0);

                  const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                  const d = imgData.data;

                  // Flood fill from corners (0,0), (width-1, 0), etc. to remove only external white background
                  const width = canvas.width;
                  const height = canvas.height;
                  const visited = new Uint8Array(width * height);
                  const queue = [];

                  function isBg(idx) {
                    const r = d[idx];
                    const g = d[idx + 1];
                    const b = d[idx + 2];
                    // Outer white background threshold
                    return r >= 242 && g >= 242 && b >= 242;
                  }

                  // Seed outer border pixels
                  for (let x = 0; x < width; x++) {
                    const idxTop = (0 * width + x) * 4;
                    if (isBg(idxTop)) { queue.push(x, 0); visited[x] = 1; }
                    const idxBot = ((height - 1) * width + x) * 4;
                    if (isBg(idxBot)) { queue.push(x, height - 1); visited[(height - 1) * width + x] = 1; }
                  }
                  for (let y = 0; y < height; y++) {
                    const idxL = (y * width + 0) * 4;
                    if (isBg(idxL) && !visited[y * width]) { queue.push(0, y); visited[y * width] = 1; }
                    const idxR = (y * width + (width - 1)) * 4;
                    if (isBg(idxR) && !visited[y * width + width - 1]) { queue.push(width - 1, y); visited[y * width + width - 1] = 1; }
                  }

                  // BFS flood fill
                  let head = 0;
                  while (head < queue.length) {
                    const cx = queue[head++];
                    const cy = queue[head++];
                    const cIdx = (cy * width + cx) * 4;
                    d[cIdx + 3] = 0; // Alpha = 0

                    const neighbors = [
                      [cx + 1, cy], [cx - 1, cy],
                      [cx, cy + 1], [cx, cy - 1]
                    ];
                    for (let i = 0; i < 4; i++) {
                      const nx = neighbors[i][0];
                      const ny = neighbors[i][1];
                      if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        const nPos = ny * width + nx;
                        if (!visited[nPos]) {
                          visited[nPos] = 1;
                          const nIdx = nPos * 4;
                          if (isBg(nIdx)) {
                            queue.push(nx, ny);
                          }
                        }
                      }
                    }
                  }

                  // Feather border pixels
                  ctx.putImageData(imgData, 0, 0);
                  resolve(canvas.toDataURL('image/png'));
                };
                img.src = 'https://cdn.shopify.com/s/files/1/1032/4541/4771/files/photo_2026-11-03_04-05-43.jpg?v=1793703987';
              });
            `
          });

          const dataUrl = result.result?.result?.value;
          if (dataUrl && dataUrl.startsWith('data:image/png;base64,')) {
            const base64 = dataUrl.replace('data:image/png;base64,', '');
            fs.writeFileSync('assets/infrared-battle-set-cutout.png', Buffer.from(base64, 'base64'));
            console.log('Successfully generated transparent PNG cutout: assets/infrared-battle-set-cutout.png');
          } else {
            console.error('Failed to get dataURL', result);
          }

          chromeProc.kill();
        };
      });
    });
  }, 1500);
}

removeBgInChrome();

