const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551';

async function verifyPDP() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9257',
    '--window-size=1200,900',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9257/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            // 1. Password unlock
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });
            await new Promise(r => setTimeout(r, 2000));

            // 2. Navigate to PDP on Live theme
            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector?preview_theme_id=197111513459'
            });
            await new Promise(r => setTimeout(r, 3500));

            // Inspect section order in DOM
            const domSections = await send('Runtime.evaluate', {
              expression: `
                Array.from(document.querySelectorAll('main#MainContent > [id^="shopify-section-"]')).map(el => {
                  const id = el.id.replace('shopify-section-', '');
                  const cls = el.className;
                  const h2 = el.querySelector('h2')?.innerText?.trim() || '';
                  const h3 = el.querySelector('h3')?.innerText?.trim() || '';
                  return { id, cls, header: h2 || h3 };
                })
              `,
              returnByValue: true
            });
            console.log('DOM Sections in <main#MainContent>:\n', JSON.stringify(domSections.result?.result?.value, null, 2));

            // Check if deleted sections are absent
            const hasDescription = await send('Runtime.evaluate', {
              expression: `!!document.querySelector('.tm-description-section, #shopify-section-description, [data-section-type="trymalora-pdp-description"]')`
            });
            const hasSpecs = await send('Runtime.evaluate', {
              expression: `!!document.querySelector('.tm-specs-section, #shopify-section-specs, [data-section-type="trymalora-pdp-specs"]')`
            });
            console.log('Has Description Section:', hasDescription.result?.result?.value);
            console.log('Has Specs Section:', hasSpecs.result?.result?.value);

            // Capture Desktop view of the transition from 3-Step Setup directly to FAQ
            await send('Runtime.evaluate', {
              expression: `
                const setupEl = document.querySelector('.tm-setup-section') || document.querySelector('.tm-how-it-works-section');
                if (setupEl) setupEl.scrollIntoView({ behavior: 'instant', block: 'end' });
              `
            });
            await new Promise(r => setTimeout(r, 1000));
            const setupToFaqShot = await send('Page.captureScreenshot', { format: 'png' });
            if (setupToFaqShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_pdp_setup_to_faq_desktop.png'), Buffer.from(setupToFaqShot.result.data, 'base64'));
              console.log('Saved qa_pdp_setup_to_faq_desktop.png');
            }

            // Capture Mobile view
            await send('Emulation.setDeviceMetricsOverride', {
              width: 390,
              height: 844,
              deviceScaleFactor: 2,
              mobile: true
            });
            await new Promise(r => setTimeout(r, 1000));
            const mobileShot = await send('Page.captureScreenshot', { format: 'png' });
            if (mobileShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_pdp_setup_to_faq_mobile.png'), Buffer.from(mobileShot.result.data, 'base64'));
              console.log('Saved qa_pdp_setup_to_faq_mobile.png');
            }

            chromeProc.kill();
            process.exit(0);
          };
        } catch (err) {
          console.error(err);
          chromeProc.kill();
          process.exit(1);
        }
      });
    });
  }, 1500);
}

