const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551';

async function verifyBuyBox() {
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9267',
    '--window-size=1200,900',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9267/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });
            await new Promise(r => setTimeout(r, 2000));

            await send('Page.navigate', {
              url: 'https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector?preview_theme_id=197111513459'
            });
            await new Promise(r => setTimeout(r, 3500));

            // Scroll to bundle box
            await send('Runtime.evaluate', {
              expression: `
                const el = document.querySelector('.zv-bundle-box');
                if (el) el.scrollIntoView({ behavior: 'instant', block: 'center' });
              `
            });
            await new Promise(r => setTimeout(r, 1000));

            const shotDesktop = await send('Page.captureScreenshot', { format: 'png' });
            if (shotDesktop?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_bundle_free_shipping_desktop.png'), Buffer.from(shotDesktop.result.data, 'base64'));
              console.log('Saved qa_bundle_free_shipping_desktop.png');
            }

            // Mobile view
            await send('Emulation.setDeviceMetricsOverride', {
              width: 390,
              height: 844,
              deviceScaleFactor: 2,
              mobile: true
            });
            await send('Runtime.evaluate', {
              expression: `
                const el = document.querySelector('.zv-bundle-box');
                if (el) el.scrollIntoView({ behavior: 'instant', block: 'center' });
              `
            });
            await new Promise(r => setTimeout(r, 1000));

            const shotMobile = await send('Page.captureScreenshot', { format: 'png' });
            if (shotMobile?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_bundle_free_shipping_mobile.png'), Buffer.from(shotMobile.result.data, 'base64'));
              console.log('Saved qa_bundle_free_shipping_mobile.png');
            }

            chromeProc.kill();
            process.exit(0);
          };
        } catch (e) {
          console.error(e);
          chromeProc.kill();
          process.exit(1);
        }
      });
    });
  }, 1500);
}

