import { shopifyFetch } from './config.mjs';

async function main() {
  const query = `
    query {
      products(first: 5) {
        edges {
          node {
            id
            title
            handle
            media(first: 20) {
              edges {
                node {
                  id
                  mediaContentType
                  ... on MediaImage {
                    image {
                      id
                      url
                      altText
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  `;
  const res = await shopifyFetch(query);
  const products = res?.data?.products?.edges || [];
  for (const p of products) {
    console.log(`Product: ${p.node.title} (${p.node.id})`);
    for (const m of p.node.media.edges) {
      console.log(`  Media ID: ${m.node.id}`);
      console.log(`  Image URL: ${m.node.image?.url}`);
    }
  }
}

main().catch(console.error);

