import { spawn } from 'child_process';
import http from 'http';
import fs from 'fs';
import path from 'path';

const ARTIFACT_DIR = 'C:/Users/Admin/.gemini/antigravity/brain/d284d670-0cfd-4f12-bbed-f8eeaea36551';
const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

function sendCdp(wsUrl, method, params = {}) {
  return new Promise((resolve, reject) => {
    const ws = new (require('ws'))(wsUrl);
    const id = 1;
    ws.on('open', () => {
      ws.send(JSON.stringify({ id, method, params }));
    });
    ws.on('message', (data) => {
      const res = JSON.parse(data.toString());
      if (res.id === id) {
        ws.close();
        if (res.error) reject(new Error(res.error.message));
        else resolve(res.result);
      }
    });
    ws.on('error', reject);
  });
}

async function capture() {
  const chromeProc = spawn(CHROME_PATH, [
    '--headless=new',
    '--remote-debugging-port=9223',
    '--no-first-run',
    '--no-default-browser-check',
    '--window-size=412,915'
  ]);

  await new Promise(r => setTimeout(r, 2000));

  try {
    const res = await fetch('http://127.0.0.1:9223/json');
    const tabs = await res.json();
    const tab = tabs[0];
    const WebSocket = (await import('ws')).default;

    const ws = new WebSocket(tab.webSocketDebuggerUrl);
    let msgId = 1;
    const send = (method, params = {}) => new Promise((resolve, reject) => {
      const id = msgId++;
      const onMsg = (data) => {
        const parsed = JSON.parse(data.toString());
        if (parsed.id === id) {
          ws.off('message', onMsg);
          if (parsed.error) reject(new Error(parsed.error.message));
          else resolve(parsed.result);
        }
      };
      ws.on('message', onMsg);
      ws.send(JSON.stringify({ id, method, params }));
    });

    await new Promise(r => ws.on('open', r));

    await send('Page.enable');
    await send('Emulation.setDeviceMetricsOverride', {
      width: 412,
      height: 915,
      deviceScaleFactor: 2,
      mobile: true
    });

    console.log('Navigating to live PDP on mobile...');
    await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector?preview_theme_id=197111513459' });
    await new Promise(r => setTimeout(r, 4000));

    // Fill storefront password if required
    await send('Runtime.evaluate', {
      expression: `
        const pass = document.getElementById('password') || document.querySelector('input[type="password"]');
        if (pass) {
          pass.value = '[STOREFRONT_PASSWORD_REDACTED]';
          const form = pass.closest('form');
          if (form) form.submit();
        }
      `
    });
    await new Promise(r => setTimeout(r, 3500));

    // Capture gallery area
    const galleryShot = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_pdp_gallery_verified.png'), Buffer.from(galleryShot.data, 'base64'));
    console.log('Saved qa_pdp_gallery_verified.png');

    // Scroll down to shipping section
    await send('Runtime.evaluate', {
      expression: `
        const el = document.getElementById('zv-doorstep-delivery');
        if (el) el.scrollIntoView({ behavior: 'instant', block: 'start' });
      `
    });
    await new Promise(r => setTimeout(r, 1500));

    const shippingShot = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_pdp_shipping_mobile_verified.png'), Buffer.from(shippingShot.data, 'base64'));
    console.log('Saved qa_pdp_shipping_mobile_verified.png');

    ws.close();
  } finally {
    chromeProc.kill();
  }
}

capture().catch(console.error);

