import { getCliToken } from './config.mjs';

const SHOP = 'ikwh1h-fx.myshopify.com';
const API_VERSION = '2026-10';

export async function shopifyGql(query, variables = {}) {
  const token = getCliToken();
  const res = await fetch(`https://${SHOP}/admin/api/${API_VERSION}/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`
    },
    body: JSON.stringify({ query, variables })
  });
  const json = await res.json();
  if (json.errors) {
    console.error('GraphQL errors:', JSON.stringify(json.errors, null, 2));
  }
  return json;
}

export async function shopifyRest(endpoint, method = 'GET', data = null) {
  const token = getCliToken();
  const url = `https://${SHOP}/admin/api/${API_VERSION}/${endpoint}`;
  const options = {
    method,
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    }
  };
  if (data) {
    options.body = JSON.stringify(data);
  }
  const res = await fetch(url, options);
  return await res.json();
}

async function checkInventory() {
  const query = `
    query {
      products(first: 50) {
        edges {
          node {
            id
            title
            status
            variants(first: 50) {
              edges {
                node {
                  id
                  title
                  price
                  inventoryPolicy
                  inventoryQuantity
                }
              }
            }
          }
        }
      }
    }
  `;
  const res = await shopifyGql(query);
  const products = res?.data?.products?.edges || [];
  console.log(`Found ${products.length} products`);
  for (const p of products) {
    console.log(`Product: ${p.node.title} (${p.node.status})`);
    for (const v of p.node.variants.edges) {
      console.log(`  Variant: ${v.node.title} | Price: ${v.node.price} | Policy: ${v.node.inventoryPolicy} | Qty: ${v.node.inventoryQuantity}`);
    }
  }
}

checkInventory().catch(console.error);

import { shopifyGql } from './manage_store_settings.mjs';

async function updateInventoryPolicyToContinue() {
  const query = `
    query {
      products(first: 50) {
        edges {
          node {
            id
            title
            variants(first: 50) {
              edges {
                node {
                  id
                  title
                  inventoryPolicy
                }
              }
            }
          }
        }
      }
    }
  `;
  const res = await shopifyGql(query);
  const products = res?.data?.products?.edges || [];

  for (const p of products) {
    console.log(`Updating product: ${p.node.title} (${p.node.id})`);
    for (const v of p.node.variants.edges) {
      console.log(`  Updating variant: ${v.node.title} (${v.node.id})...`);
      const updateMutation = `
        mutation variantUpdate($input: ProductVariantInput!) {
          productVariantUpdate(input: $input) {
            productVariant {
              id
              title
              inventoryPolicy
            }
            userErrors {
              field
              message
            }
          }
        }
      `;
      const updateRes = await shopifyGql(updateMutation, {
        input: {
          id: v.node.id,
          inventoryPolicy: 'CONTINUE'
        }
      });
      console.log('  Result:', JSON.stringify(updateRes?.data?.productVariantUpdate));
    }
  }
}

updateInventoryPolicyToContinue().catch(console.error);

