import { spawn } from 'child_process';
import http from 'http';
import fs from 'fs';

const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

async function testCartAndBuyNow() {
  const chromeProc = spawn(CHROME_PATH, [
    '--headless=new',
    '--remote-debugging-port=9269',
    '--no-first-run',
    '--no-default-browser-check',
    '--window-size=1280,900',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  await new Promise(r => setTimeout(r, 2500));

  try {
    const res = await fetch('http://127.0.0.1:9269/json');
    const tabs = await res.json();
    const tab = tabs.find(t => t.type === 'page') || tabs[0];

    const ws = new WebSocket(tab.webSocketDebuggerUrl);
    let msgId = 1;
    const send = (method, params = {}) => new Promise((resolve, reject) => {
      const id = msgId++;
      const onMsg = (event) => {
        const parsed = JSON.parse(event.data);
        if (parsed.id === id) {
          ws.removeEventListener('message', onMsg);
          if (parsed.error) reject(new Error(parsed.error.message));
          else resolve(parsed.result);
        }
      };
      ws.addEventListener('message', onMsg);
      ws.send(JSON.stringify({ id, method, params }));
    });

    await new Promise(r => { ws.onopen = r; });

    await send('Page.enable');
    await send('Runtime.enable');

    // Unlock password page
    await send('Runtime.evaluate', {
      expression: `
        const input = document.querySelector("#password, input[name='password']");
        if (input) {
          input.value = "[STOREFRONT_PASSWORD_REDACTED]";
          const form = input.closest("form");
          if (form) form.submit();
        }
      `
    });
    await new Promise(r => setTimeout(r, 2000));

    // Navigate to product page
    console.log('Navigating to product page...');
    await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector' });
    await new Promise(r => setTimeout(r, 4000));

    // Check ATC button
    const atcCheck = await send('Runtime.evaluate', {
      expression: `
        (() => {
          const btn = document.getElementById('zvBtnClaim');
          const buyNow = document.getElementById('zvBtnBuyNow');
          const cards = document.querySelectorAll('.zv-bundle-card');
          return {
            hasAtc: !!btn,
            atcText: btn ? btn.innerText.trim() : null,
            hasBuyNow: !!buyNow,
            buyNowText: buyNow ? buyNow.innerText.trim() : null,
            bundleCardCount: cards.length
          };
        })()
      `,
      returnByValue: true
    });
    console.log('Buttons check:', atcCheck.result.value);

    // Test clicking Add to Cart
    console.log('Clicking Add to Cart...');
    const atcClickRes = await send('Runtime.evaluate', {
      expression: `
        (async () => {
          const btn = document.getElementById('zvBtnClaim');
          if (btn) btn.click();
          await new Promise(r => setTimeout(r, 2000));
          const drawer = document.getElementById('willaCartDrawer');
          const cartRes = await fetch('/cart.js').then(r => r.json());
          return {
            drawerActive: drawer ? drawer.classList.contains('active') : false,
            cartItemCount: cartRes.item_count,
            cartTotal: cartRes.total_price,
            items: cartRes.items.map(i => ({ id: i.id, title: i.title, quantity: i.quantity, price: i.price }))
          };
        })()
      `,
      awaitPromise: true,
      returnByValue: true
    });
    console.log('ATC Result:', JSON.stringify(atcClickRes.result.value, null, 2));

    // Test Buy Now button URL/redirection
    console.log('Checking Buy Now redirect target...');
    const buyNowCheck = await send('Runtime.evaluate', {
      expression: `
        (() => {
          const buyNow = document.getElementById('zvBtnBuyNow');
          return {
            buyNowExists: !!buyNow,
            buyNowDisabled: buyNow ? buyNow.disabled : null
          };
        })()
      `,
      returnByValue: true
    });
    console.log('Buy now state:', buyNowCheck.result.value);

    ws.close();
  } finally {
    chromeProc.kill();
  }
}

testCartAndBuyNow().catch(console.error);

