async function searchSchemaForTip() {
  const query = `
    query {
      __schema {
        types {
          name
          kind
          fields {
            name
          }
        }
      }
    }
  `;
  const res = await shopifyGql(query);
  const types = res?.data?.__schema?.types || [];
  for (const t of types) {
    if (t.name && (t.name.toLowerCase().includes('tip') || t.name.toLowerCase().includes('checkout'))) {
      console.log(`Type: ${t.name} (${t.kind})`);
    }
    if (t.fields) {
      for (const f of t.fields) {
        if (f.name.toLowerCase().includes('tip')) {
          console.log(`Field with 'tip': ${t.name}.${f.name}`);
        }
      }
    }
  }
}

