import { shopifyGql } from './manage_store_settings.mjs';

async function updateShipping() {
  const profileId = "gid://shopify/DeliveryProfile/138212278643";
  const locationGroupId = "gid://shopify/DeliveryLocationGroup/140084150643";
  const domesticZoneId = "gid://shopify/DeliveryZone/646226674035";

  const mutation = `
    mutation deliveryProfileUpdate($id: ID!, $profile: DeliveryProfileInput!) {
      deliveryProfileUpdate(id: $id, profile: $profile) {
        profile {
          id
          name
          profileLocationGroups {
            locationGroup {
              id
            }
            locationGroupZones(first: 10) {
              edges {
                node {
                  zone {
                    id
                    name
                  }
                  methodDefinitions(first: 10) {
                    edges {
                      node {
                        id
                        name
                        active
                        rateProvider {
                          ... on DeliveryRateDefinition {
                            price {
                              amount
                              currencyCode
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const profileInput = {
    locationGroupsToUpdate: [
      {
        id: locationGroupId,
        zonesToUpdate: [
          {
            id: domesticZoneId,
