              },
              {
                name: "Free Tracked Shipping (Orders $70+)",
                rateDefinition: {
                  price: {
                    amount: "0.00",
                    currencyCode: "USD"
                  }
                },
                priceConditionsToCreate: [
                  {
                    criteria: {
                      amount: "70.00",
                      currencyCode: "USD"
                    },
                    operator: "GREATER_THAN_OR_EQUAL_TO"
                  }
                ]
              }
            ]
          }
        ],
        zonesToCreate: [
          {
            name: "Worldwide (Rest of World)",
            countries: [
              {
                restOfWorld: true
              }
            ],
            methodDefinitionsToCreate: [
              {
                name: "Standard Shipping (Under $70)",
                rateDefinition: {
                  price: {
                    amount: "4.95",
                    currencyCode: "USD"
                  }
                },
                priceConditionsToCreate: [
                  {
                    criteria: {
                      amount: "69.99",
                      currencyCode: "USD"
                    },
                    operator: "LESS_THAN_OR_EQUAL_TO"
                  }
                ]
              },
              {
                name: "Free Tracked Shipping (Orders $70+)",
                rateDefinition: {
                  price: {
                    amount: "0.00",
                    currencyCode: "USD"
                  }
                },
                priceConditionsToCreate: [
                  {
                    criteria: {
                      amount: "70.00",
