      }
    ],
    methodDefinitionsToDelete: [
      "gid://shopify/DeliveryMethodDefinition/1240592384371",
      "gid://shopify/DeliveryMethodDefinition/1240592417139"
    ]
  };

  const res = await shopifyGql(mutation, {
    id: profileId,
    profile: profileInput
  });

  console.log(JSON.stringify(res, null, 2));
}

