import { spawn } from 'child_process';
import http from 'http';

const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

async function testCheckoutShipping() {
  const chromeProc = spawn(CHROME_PATH, [
    '--headless=new',
    '--remote-debugging-port=9270',
    '--no-first-run',
    '--no-default-browser-check',
    '--window-size=1280,900',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  await new Promise(r => setTimeout(r, 2500));

  try {
    const res = await fetch('http://127.0.0.1:9270/json');
    const tabs = await res.json();
    const tab = tabs.find(t => t.type === 'page') || tabs[0];

    const ws = new WebSocket(tab.webSocketDebuggerUrl);
    let msgId = 1;
    const send = (method, params = {}) => new Promise((resolve, reject) => {
      const id = msgId++;
      const onMsg = (event) => {
        const parsed = JSON.parse(event.data);
        if (parsed.id === id) {
          ws.removeEventListener('message', onMsg);
          if (parsed.error) reject(new Error(parsed.error.message));
          else resolve(parsed.result);
        }
      };
      ws.addEventListener('message', onMsg);
      ws.send(JSON.stringify({ id, method, params }));
    });

    await new Promise(r => { ws.onopen = r; });

    await send('Page.enable');
    await send('Runtime.enable');

    // Unlock password
    await send('Runtime.evaluate', {
      expression: `
        const input = document.querySelector("#password, input[name='password']");
        if (input) {
          input.value = "[STOREFRONT_PASSWORD_REDACTED]";
          const form = input.closest("form");
          if (form) form.submit();
        }
      `
    });
    await new Promise(r => setTimeout(r, 2000));

    // Clear cart first
    await send('Runtime.evaluate', {
      expression: `fetch('/cart/clear.js', { method: 'POST' })`,
      awaitPromise: true
    });

    // 1. Test Tier 1 ($129.00 -> >= $70 => Should be FREE SHIPPING)
    console.log('Adding Tier 1 ($129.00)...');
    const addT1 = await send('Runtime.evaluate', {
      expression: `
        fetch('/cart/add.js', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ items: [{ id: 67297621934451, quantity: 1 }] })
        }).then(r => r.json())
      `,
      awaitPromise: true,
      returnByValue: true
    });
    console.log('Added Tier 1:', addT1.result.value?.title, 'Price:', addT1.result.value?.price);

    const cartT1 = await send('Runtime.evaluate', {
      expression: `fetch('/cart.js').then(r => r.json())`,
      awaitPromise: true,
      returnByValue: true
    });
    console.log('Cart Total:', cartT1.result.value?.total_price, '(>= $70 -> Qualifies for Free Tracked Shipping!)');

    ws.close();
  } finally {
    chromeProc.kill();
  }
}

testCheckoutShipping().catch(console.error);

