import { getCliToken } from './config.mjs';

async function main() {
  const token = getCliToken();
  const shopifyGql = async (query, variables = {}) => {
    const res = await fetch('https://ikwh1h-fx.myshopify.com/admin/api/2026-10/graphql.json', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: JSON.stringify({ query, variables })
    });
    return await res.json();
  };

  const getRes = await shopifyGql(`
    query {
      productByHandle(handle: "metallic-silver-anti-rust-renovation-coating") {
        id
        options {
          id
          name
          optionValues {
            id
            name
          }
        }
        variants(first: 10) {
          edges {
            node {
              id
              title
              price
            }
          }
        }
      }
    }
  `);

  const p = getRes.data.productByHandle;
  console.log('Current product:', JSON.stringify(p, null, 2));

  const opt = p.options[0];
  const updateRes = await shopifyGql(`
    mutation updateOpt(
      $productId: ID!,
      $option: OptionUpdateInput!,
      $optionValuesToAdd: [OptionValueCreateInput!],
      $optionValuesToUpdate: [OptionValueUpdateInput!],
      $variantStrategy: ProductOptionUpdateVariantStrategy
    ) {
      productOptionUpdate(
        productId: $productId,
        option: $option,
        optionValuesToAdd: $optionValuesToAdd,
        optionValuesToUpdate: $optionValuesToUpdate,
        variantStrategy: $variantStrategy
      ) {
        userErrors {
          field
          message
        }
        product {
          id
          options {
            name
            values
          }
          variants(first: 10) {
            edges {
              node {
                id
                title
                price
              }
            }
          }
        }
      }
    }
  `, {
    productId: p.id,
    option: {
      id: opt.id,
      name: 'Package'
    },
    optionValuesToUpdate: [
      {
        id: opt.optionValues[0].id,
        name: '1 Can (100g Starter Kit)'
      }
    ],
    optionValuesToAdd: [
      { name: '2 Cans (Renovation Pack - 10% OFF)' },
      { name: '3 Cans (Complete Home Pack - 20% OFF)' }
    ],
    variantStrategy: 'MANAGE'
  });

  console.log('Update res:', JSON.stringify(updateRes, null, 2));
}

main().catch(console.error);

