<style>
  .tm-pkg-section {
    padding: 72px 0;
    background: #FFFFFF;
    border-top: 1px solid var(--zv-pdp-line, #EAD7DD);
    border-bottom: 1px solid var(--zv-pdp-line, #EAD7DD);
    font-family: var(--zv-font-body, 'Inter', system-ui, sans-serif);
    color: var(--zv-pdp-text, #2B1B24);
  }

  .tm-pkg-header {
    text-align: center;
    max-width: 680px;
    margin: 0 auto 48px;
  }

  .tm-pkg-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 14px;
    border-radius: var(--zv-radius-full, 9999px);
    background: var(--zv-pdp-tint, #F8E4EB);
    color: var(--zv-pdp-accent, #B0476E);
    border: 1px solid var(--zv-pdp-line, #EAD7DD);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-bottom: 14px;
  }

  .tm-pkg-title {
    font-family: var(--zv-font-heading, 'Fraunces', Georgia, serif);
    font-size: 34px;
    font-weight: 600;
    color: var(--zv-pdp-heading, #2B1B24);
    line-height: 1.18;
    letter-spacing: -0.6px;
    margin: 0 0 12px;
  }

  @media screen and (min-width: 768px) {
    .tm-pkg-title {
      font-size: 38px;
    }
  }

  .tm-pkg-subtitle {
    font-size: 15px;
    line-height: 1.6;
    color: var(--zv-pdp-body, #4A3841);
    margin: 0;
  }

  .tm-pkg-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 20px;
  }

  .tm-pkg-card {
    background: var(--zv-pdp-bg, #FFF8F5);
    border: 1px solid var(--zv-pdp-line, #EAD7DD);
    border-radius: var(--zv-radius-md, 12px);
    padding: 24px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    transition: all 0.25s ease;
  }

  .tm-pkg-card:hover {
    border-color: var(--zv-pdp-accent, #B0476E);
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(43, 27, 36, 0.05);
  }

  .tm-pkg-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    margin-bottom: 16px;
  }

  .tm-pkg-icon-wrap {
    width: 44px;
    height: 44px;
    border-radius: var(--zv-radius-sm, 8px);
    background: #FFFFFF;
    border: 1px solid var(--zv-pdp-line, #EAD7DD);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--zv-pdp-accent, #B0476E);
  }

  .tm-pkg-count-badge {
    font-size: 11.5px;
    font-weight: 800;
    padding: 3px 10px;
    border-radius: var(--zv-radius-full, 9999px);
    background: var(--zv-pdp-surface, #FBEDE8);
    color: var(--zv-pdp-cta, #6B1E46);
    letter-spacing: 0.5px;
  }

  .tm-pkg-name {
    font-family: var(--zv-font-heading, 'Fraunces', Georgia, serif);
    font-size: 18px;
    font-weight: 600;
    color: var(--zv-pdp-heading, #2B1B24);
    margin: 0 0 8px;
  }

  .tm-pkg-desc {
    font-size: 13.5px;
    line-height: 1.55;
    color: var(--zv-pdp-body, #4A3841);
    margin: 0;
  }
</style>

