            <div class="tm-pkg-card-top">
              <div class="tm-pkg-icon-wrap"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 14 14"></polyline></svg></div>
              <span class="tm-pkg-count-badge">1× INCLUDED</span>
            </div>
