    display: flex;
    flex-direction: column;
    gap: 64px;
    margin-bottom: 72px;
  }

  .tm-story-row {
    display: grid;
    grid-template-columns: 1fr;
    gap: 36px;
    align-items: center;
  }

  @media screen and (min-width: 860px) {
    .tm-story-row {
      grid-template-columns: 1fr 1fr;
      gap: 56px;
    }
    .tm-story-row.reverse {
      direction: rtl;
    }
    .tm-story-row.reverse > * {
      direction: ltr;
    }
