  .tm-story-eyebrow {
    display: block;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1.2px;
    text-transform: uppercase;
    color: var(--zv-pdp-accent, #B0476E);
    margin-bottom: 8px;
  }

  .tm-story-heading {
    font-family: var(--zv-font-heading, 'Fraunces', Georgia, serif);
    font-size: 26px;
    font-weight: 600;
    color: var(--zv-pdp-heading, #2B1B24);
    line-height: 1.25;
    letter-spacing: -0.4px;
    margin: 0 0 14px;
  }

  @media screen and (min-width: 768px) {
    .tm-story-heading {
      font-size: 30px;
    }
  }

  .tm-story-desc {
    font-size: 14.5px;
    line-height: 1.6;
    color: var(--zv-pdp-body, #4A3841);
    margin: 0 0 20px;
