  .tm-faq-item {
    border-top: 1px solid var(--zv-pdp-line, #EAD7DD);
  }

  .tm-faq-summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 22px 0;
    cursor: pointer;
    font-family: var(--zv-font-heading, 'Fraunces', Georgia, serif);
    font-size: 17.5px;
    font-weight: 600;
    color: var(--zv-pdp-heading, #2B1B24);
