const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');
const path = require('path');

const ARTIFACT_DIR = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551';
const THEME_ID = '197144805747';

async function runQA() {
  console.log('Launching headless Chrome for Draft Theme #', THEME_ID);
  const chromeProc = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9258',
    '--window-size=1280,950',
    'https://ikwh1h-fx.myshopify.com/password'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9258/json', (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', async () => {
        try {
          const list = JSON.parse(raw);
          const page = list.find(p => p.type === 'page');
          if (!page) { chromeProc.kill(); return; }

          const ws = new WebSocket(page.webSocketDebuggerUrl);
          let id = 1;
          function send(method, params = {}) {
            return new Promise((resolve) => {
              const reqId = id++;
              const handler = (event) => {
                const data = JSON.parse(event.data);
                if (data.id === reqId) {
                  ws.removeEventListener('message', handler);
                  resolve(data);
                }
              };
              ws.addEventListener('message', handler);
              ws.send(JSON.stringify({ id: reqId, method, params }));
            });
          }

          ws.onopen = async () => {
            await send('Runtime.enable');
            await send('Page.enable');

            // 1. Enter storefront password
            console.log('Unlocking storefront password...');
            await send('Runtime.evaluate', {
              expression: `
                const input = document.querySelector("#password, input[name='password']");
                if (input) {
                  input.value = "[STOREFRONT_PASSWORD_REDACTED]";
                  const form = input.closest("form");
                  if (form) form.submit();
                }
              `
            });
            await new Promise(r => setTimeout(r, 2000));

            // 2. Capture Desktop Homepage on Draft Theme
            console.log('Capturing Desktop Homepage on Draft Theme...');
            await send('Emulation.setDeviceMetricsOverride', {
              width: 1280,
              height: 900,
              deviceScaleFactor: 1,
              mobile: false
            });
            await send('Page.navigate', {
              url: `https://ikwh1h-fx.myshopify.com/?preview_theme_id=${THEME_ID}`
            });
            await new Promise(r => setTimeout(r, 3500));

            const homeDeskShot = await send('Page.captureScreenshot', { format: 'png' });
            if (homeDeskShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_draft_homepage_desktop.png'), Buffer.from(homeDeskShot.result.data, 'base64'));
              console.log('Saved qa_draft_homepage_desktop.png');
            }

            // Scroll down to Category cards & Featured products
            await send('Runtime.evaluate', {
              expression: `
                const el = document.getElementById('tmCategories') || document.getElementById('tmFeaturedProducts');
                if (el) el.scrollIntoView({ behavior: 'instant', block: 'start' });
              `
            });
            await new Promise(r => setTimeout(r, 1000));
            const homeFeatShot = await send('Page.captureScreenshot', { format: 'png' });
            if (homeFeatShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_draft_categories_and_products.png'), Buffer.from(homeFeatShot.result.data, 'base64'));
              console.log('Saved qa_draft_categories_and_products.png');
            }

            // 3. Capture Mobile Homepage (390px)
            console.log('Capturing Mobile Homepage on Draft Theme...');
            await send('Emulation.setDeviceMetricsOverride', {
              width: 390,
              height: 844,
              deviceScaleFactor: 2,
              mobile: true
            });
            await send('Page.navigate', {
              url: `https://ikwh1h-fx.myshopify.com/?preview_theme_id=${THEME_ID}`
            });
            await new Promise(r => setTimeout(r, 3000));

            const homeMobileShot = await send('Page.captureScreenshot', { format: 'png' });
            if (homeMobileShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_draft_homepage_mobile.png'), Buffer.from(homeMobileShot.result.data, 'base64'));
              console.log('Saved qa_draft_homepage_mobile.png');
            }

            // Scroll mobile to products grid
            await send('Runtime.evaluate', {
              expression: `
                const el = document.getElementById('tmFeaturedProducts');
                if (el) el.scrollIntoView({ behavior: 'instant', block: 'start' });
              `
            });
            await new Promise(r => setTimeout(r, 1000));
            const mobileGridShot = await send('Page.captureScreenshot', { format: 'png' });
            if (mobileGridShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_draft_products_grid_mobile.png'), Buffer.from(mobileGridShot.result.data, 'base64'));
              console.log('Saved qa_draft_products_grid_mobile.png');
            }

            // 4. Capture Desktop PDP V2 on Draft Theme
            console.log('Capturing Desktop PDP V2 on Draft Theme...');
            await send('Emulation.setDeviceMetricsOverride', {
              width: 1280,
              height: 900,
              deviceScaleFactor: 1,
              mobile: false
            });
            await send('Page.navigate', {
              url: `https://ikwh1h-fx.myshopify.com/products/kids-infrared-battle-blaster-set-with-target-projector?preview_theme_id=${THEME_ID}`
            });
            await new Promise(r => setTimeout(r, 3500));

            const pdpDeskShot = await send('Page.captureScreenshot', { format: 'png' });
            if (pdpDeskShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_draft_pdp_desktop.png'), Buffer.from(pdpDeskShot.result.data, 'base64'));
              console.log('Saved qa_draft_pdp_desktop.png');
            }

            // Scroll down to What's in the Box & Setup
            await send('Runtime.evaluate', {
              expression: `
                const el = document.getElementById('tmPackageContents') || document.getElementById('tmHowItWorks');
                if (el) el.scrollIntoView({ behavior: 'instant', block: 'start' });
              `
            });
            await new Promise(r => setTimeout(r, 1000));
            const pdpBodyShot = await send('Page.captureScreenshot', { format: 'png' });
            if (pdpBodyShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_draft_pdp_body.png'), Buffer.from(pdpBodyShot.result.data, 'base64'));
              console.log('Saved qa_draft_pdp_body.png');
            }

            // 5. Test Add to Cart & Cart Drawer
            console.log('Testing Add to Cart interaction...');
            const atcResult = await send('Runtime.evaluate', {
              expression: `
                const btn = document.getElementById('zvBtnClaim');
                if (btn) {
                  btn.click();
                  'clicked';
                } else {
                  'btn not found';
                }
              `
            });
            console.log('ATC click result:', atcResult?.result?.value);
            await new Promise(r => setTimeout(r, 2000));

            const cartDrawerShot = await send('Page.captureScreenshot', { format: 'png' });
            if (cartDrawerShot?.result?.data) {
              fs.writeFileSync(path.join(ARTIFACT_DIR, 'qa_draft_cart_drawer.png'), Buffer.from(cartDrawerShot.result.data, 'base64'));
              console.log('Saved qa_draft_cart_drawer.png');
            }

            console.log('ALL QA CAPTURES COMPLETED SUCCESSFULLY!');
            chromeProc.kill();
            process.exit(0);
          };
        } catch (e) {
          console.error(e);
          chromeProc.kill();
          process.exit(1);
        }
      });
    });
  }, 1500);
}

runQA();

