const { spawn } = require('child_process');
const http = require('http');

async function checkChrome() {
  const chrome = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
    '--headless=new',
    '--remote-debugging-port=9265',
    'https://trymalora.com/products/kids-infrared-battle-blaster-set-with-target-projector?preview_theme_id=197144805747'
  ]);

  setTimeout(() => {
    http.get('http://127.0.0.1:9265/json', res => {
      let d = ''; res.on('data', c => d += c);
      res.on('end', async () => {
        const tabs = JSON.parse(d);
        const tab = tabs.find(t => t.type === 'page');
        const ws = new WebSocket(tab.webSocketDebuggerUrl);
        let id = 1;
        function send(method, params = {}) {
          return new Promise(r => {
            const reqId = id++;
            const h = e => {
              const data = JSON.parse(e.data);
              if (data.id === reqId) { ws.removeEventListener('message', h); r(data); }
            };
            ws.addEventListener('message', h);
            ws.send(JSON.stringify({ id: reqId, method, params }));
          });
        }
        await new Promise(r => setTimeout(r, 4000));
        const resUrl = await send('Runtime.evaluate', { expression: 'window.location.href' });
        const resTitle = await send('Runtime.evaluate', { expression: 'document.title' });
        const resBody = await send('Runtime.evaluate', { expression: 'document.body.innerText.slice(0, 300)' });
        console.log('URL:', resUrl.result.value);
        console.log('Title:', resTitle.result.value);
        console.log('Body:', resBody.result.value);
        chrome.kill();
      });
    });
  }, 2000);
}
checkChrome();
