/* ==========================================================================
   16. OPTION SELECTORS (COLOR & SIZE PILLS / SWATCHES)
   ========================================================================== */
.zv-option-section {
  margin: 16px 0;
}

.zv-option-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: var(--zv-pdp-muted, #7A6670);
  margin-bottom: 8px;
}

.zv-option-label strong {
  color: var(--zv-pdp-heading, #2B1B24);
  font-weight: 700;
}

.zv-option-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.zv-option-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 8px;
  border: 1.5px solid var(--zv-pdp-line, #EAD7DD);
  background: #FFFFFF;
  color: var(--zv-pdp-heading, #2B1B24);
  font-family: var(--zv-font-body, 'Inter', system-ui, sans-serif);
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.zv-option-pill:hover {
  border-color: var(--zv-pdp-accent, #B0476E);
}

.zv-option-pill.active {
  border-color: var(--zv-pdp-accent, #B0476E);
  background: var(--zv-pdp-tint, #F8E4EB);
  color: var(--zv-pdp-accent, #B0476E);
}

.zv-swatch {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  flex-shrink: 0;
  display: inline-block;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.1);
}

.zv-pill-price {
  font-size: 12px;
  font-weight: 700;
  opacity: 0.85;
}

/* Shipping Badge dynamic threshold */
.zv-bundle-shipping-badge.locked {
  color: var(--zv-pdp-muted, #7A6670);
  opacity: 0.85;
}

.zv-bundle-shipping-badge.unlocked {
  color: #059669;
  font-weight: 700;
}

.zv-bundle-shipping-badge.unlocked svg {
  color: #059669;
}

/* Gallery Video Elements */
.zv-pdp-thumb.video-thumb {
  position: relative;
}

.zv-thumb-video-icon {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.7);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.zv-thumb-video-icon svg {
  width: 12px;
  height: 12px;
  fill: #FFFFFF;
  margin-left: 2px;
}

.zv-pdp-video {
  width: 100%;
  height: 100%;
