// 2b. TILE REFINISHING SPECIALIZED BUNDLE & OPTION CONTROLLER (TASKS 1, 2, 3)
const tileBundleCards = buyBox.querySelectorAll('.zv-tile-bundle-card');
if (tileBundleCards.length > 0) {
  let selectedColor = 'Pure White';
  let selectedSize = '100g';
  let selectedTier = 1;

  const colorPills = buyBox.querySelectorAll('#zvColorPills .zv-option-pill');
  const sizePills = buyBox.querySelectorAll('#zvSizePills .zv-option-pill');
  const shippingBadge = document.getElementById('zvBundleShippingBadge');
  const shippingText = document.getElementById('zvBundleShippingText');

  const priceMatrix = {
    '100g': {
      base: 16.99,
      b1: { total: 16.99, unit: 16.99, orig: 16.99, save: 0 },
      b2: { total: 32.28, unit: 16.14, orig: 33.98, save: 1.70 },
      b3: { total: 45.87, unit: 15.29, orig: 50.97, save: 5.10 }
    },
    '300g': {
      base: 29.99,
      b1: { total: 29.99, unit: 29.99, orig: 29.99, save: 0 },
      b2: { total: 56.98, unit: 28.49, orig: 59.98, save: 3.00 },
      b3: { total: 80.97, unit: 26.99, orig: 89.97, save: 9.00 }
    },
    '500g': {
      base: 39.99,
      b1: { total: 39.99, unit: 39.99, orig: 39.99, save: 0 },
      b2: { total: 75.98, unit: 37.99, orig: 79.98, save: 4.00 },
      b3: { total: 107.97, unit: 35.99, orig: 119.97, save: 12.00 }
    }
  };

  let variantMatrix = {};
  const matrixEl = document.getElementById('zvTileVariantMatrix');
  if (matrixEl) {
    try {
      variantMatrix = JSON.parse(matrixEl.textContent);
    } catch(e) {}
  }

  function updateTileState() {
    const pInfo = priceMatrix[selectedSize] || priceMatrix['100g'];

    // Update Buy 1
    const b1Tot = document.getElementById('zvTileB1Total');
    const b1Un = document.getElementById('zvTileB1Unit');
    if (b1Tot) b1Tot.textContent = '$' + pInfo.b1.total.toFixed(2);
    if (b1Un) b1Un.textContent = '$' + pInfo.b1.unit.toFixed(2) + ' / box';

    // Update Buy 2
    const b2Tot = document.getElementById('zvTileB2Total');
    const b2Un = document.getElementById('zvTileB2Unit');
    const b2Orig = document.getElementById('zvTileB2Orig');
    const b2Save = document.getElementById('zvTileB2Save');
    if (b2Tot) b2Tot.textContent = '$' + pInfo.b2.total.toFixed(2);
    if (b2Un) b2Un.textContent = '$' + pInfo.b2.unit.toFixed(2) + ' / box';
    if (b2Orig) b2Orig.textContent = '$' + pInfo.b2.orig.toFixed(2);
    if (b2Save) b2Save.textContent = '$' + pInfo.b2.save.toFixed(2);

    // Update Buy 3
    const b3Tot = document.getElementById('zvTileB3Total');
    const b3Un = document.getElementById('zvTileB3Unit');
    const b3Orig = document.getElementById('zvTileB3Orig');
    const b3Save = document.getElementById('zvTileB3Save');
    if (b3Tot) b3Tot.textContent = '$' + pInfo.b3.total.toFixed(2);
    if (b3Un) b3Un.textContent = '$' + pInfo.b3.unit.toFixed(2) + ' / box';
    if (b3Orig) b3Orig.textContent = '$' + pInfo.b3.orig.toFixed(2);
    if (b3Save) b3Save.textContent = '$' + pInfo.b3.save.toFixed(2);

    // Current active tier
    const activeTierKey = 'b' + selectedTier;
    const currentTierData = pInfo[activeTierKey];
    const activeTotal = currentTierData.total;
    const activeOrig = currentTierData.orig;
    const activeCents = Math.round(activeTotal * 100);

    // Hero price
    if (priceActiveEl) priceActiveEl.textContent = '$' + activeTotal.toFixed(2);
    if (stickyPrice) stickyPrice.textContent = '$' + activeTotal.toFixed(2);
    if (priceCompareEl) {
      if (activeOrig > activeTotal) {
        priceCompareEl.textContent = '$' + activeOrig.toFixed(2);
        priceCompareEl.style.display = 'inline';
        if (priceSavingsEl) {
          const saveAmt = activeOrig - activeTotal;
          const pct = selectedTier === 2 ? 5 : (selectedTier === 3 ? 10 : 0);
          priceSavingsEl.textContent = 'SAVE $' + saveAmt.toFixed(2) + (pct ? ' (' + pct + '% OFF)' : '');
          priceSavingsEl.style.display = 'inline';
        }
      } else {
        priceCompareEl.style.display = 'none';
        if (priceSavingsEl) priceSavingsEl.style.display = 'none';
      }
    }

    // CTA Label
    updateCtaLabels(activeCents);
    const claimSub = claimBtn ? claimBtn.querySelector('.zv-atc-sub') : null;
    if (claimSub) claimSub.textContent = '30-Day Returns on Eligible Items';

    // Active Qty
    activeQty = selectedTier;

    // Match Variant ID
    const combo1 = selectedColor + ' / ' + selectedSize;
    const combo2 = selectedColor + ' (with Brush)';
    const matched = variantMatrix[combo1] || variantMatrix[combo2];
    if (matched && matched.id) {
      activeVariantId = matched.id.replace('gid://shopify/ProductVariant/', '');
    }

    // Shipping Rule (TASK 1: Threshold $70)
    const isFreeShipping = activeTotal >= 70.0;
    if (shippingBadge) {
      if (isFreeShipping) {
        shippingBadge.className = 'zv-bundle-shipping-badge unlocked';
        if (shippingText) shippingText.textContent = 'Free Shipping Unlocked ($70+)';
      } else {
        shippingBadge.className = 'zv-bundle-shipping-badge locked';
        if (shippingText) shippingText.textContent = 'Free Shipping for Orders Over $70';
      }
    }

    if (giftUnlockBox) {
      const iconEl = document.getElementById('zvGiftIcon');
      if (isFreeShipping) {
        giftUnlockBox.classList.add('unlocked');
        if (giftStatusBadge) giftStatusBadge.textContent = 'UNLOCKED';
        if (iconEl) iconEl.textContent = '🚚';
        if (giftTitle) giftTitle.textContent = 'FREE Tracked US Shipping Unlocked';
        if (giftSub) giftSub.textContent = 'Your order qualifies for fast free shipping from US hubs!';
      } else {
        giftUnlockBox.classList.remove('unlocked');
        if (giftStatusBadge) giftStatusBadge.textContent = 'STANDARD';
        if (iconEl) iconEl.textContent = '📦';
        if (giftTitle) giftTitle.textContent = 'Standard US Shipping ($4.95)';
        const diff = (70 - activeTotal).toFixed(2);
        if (giftSub) giftSub.textContent = 'Add $' + diff + ' more to unlock FREE tracked delivery';
      }
    }
  }

  colorPills.forEach(pill => {
    pill.addEventListener('click', function() {
      colorPills.forEach(p => p.classList.remove('active'));
      this.classList.add('active');
      selectedColor = this.getAttribute('data-color');
      const lbl = document.getElementById('zvSelectedColorLabel');
      if (lbl) lbl.textContent = selectedColor;
      updateTileState();
    });
  });

  sizePills.forEach(pill => {
    pill.addEventListener('click', function() {
      sizePills.forEach(p => p.classList.remove('active'));
      this.classList.add('active');
      selectedSize = this.getAttribute('data-size');
      const lbl = document.getElementById('zvSelectedSizeLabel');
      if (lbl) lbl.textContent = selectedSize;
      updateTileState();
    });
  });

  tileBundleCards.forEach(card => {
    card.addEventListener('click', function() {
      tileBundleCards.forEach(c => c.classList.remove('selected'));
      this.classList.add('selected');
      selectedTier = parseInt(this.getAttribute('data-bundle-tier'), 10) || 1;
      updateTileState();
    });
  });

  // Initial run
  updateTileState();
}

