      } else {
        throw new Error(errData.description || errData.message || 'Failed to add items to cart');
      }
    }

    if (goToCheckout) {
      let checkoutUrl = '/checkout';
      if (discountCode) {
        checkoutUrl += '?discount=' + encodeURIComponent(discountCode);
      }
      window.location.href = checkoutUrl;
      return;
