const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const userDataDir = 'C:\\Users\\Admin\\.chrome-headless-qa-tp';

function getWsUrl(port) {
  return new Promise((resolve, reject) => {
    let retries = 0;
    const interval = setInterval(() => {
      http.get(`http://127.0.0.1:${port}/json`, res => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          try {
            const list = JSON.parse(data);
            if (list.length > 0 && list[0].webSocketDebuggerUrl) {
              clearInterval(interval);
              resolve(list[0].webSocketDebuggerUrl);
            }
          } catch(e) {}
        });
      }).on('error', () => {});
      retries++;
      if (retries > 30) {
        clearInterval(interval);
        reject(new Error('Timeout waiting for Chrome remote debugging port'));
      }
    }, 200);
  });
}

async function run() {
  const port = 9334;
  const chromeProcess = spawn(chromePath, [
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${userDataDir}`,
    '--headless=new',
    '--disable-gpu',
    '--no-first-run',
    '--no-default-browser-check'
  ]);

  try {
    const wsUrl = await getWsUrl(port);
    const WebSocket = require('ws');
    const ws = new WebSocket(wsUrl);

    await new Promise(r => ws.on('open', r));

    let msgId = 1;
    function send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const id = msgId++;
        function handler(data) {
          const res = JSON.parse(data);
          if (res.id === id) {
            ws.off('message', handler);
            if (res.error) reject(res.error);
            else resolve(res.result);
          }
        }
        ws.on('message', handler);
        ws.send(JSON.stringify({ id, method, params }));
      });
    }

    await send('Page.enable');
    await send('Runtime.enable');
    await send('DOM.enable');

    // Desktop
    await send('Emulation.setDeviceMetricsOverride', {
      width: 1440,
      height: 900,
      deviceScaleFactor: 1,
      mobile: false
    });

    console.log('Navigating to Tile Paint PDP on Draft Theme...');
    await send('Page.navigate', {
      url: 'https://ikwh1h-fx.myshopify.com/products/tile-refinishing-paint-restoration-kit?preview_theme_id=197144805747'
    });
    await new Promise(r => setTimeout(r, 3500));

    // Evaluate Trustpilot element bounding box & single-line check
    const evalRes = await send('Runtime.evaluate', {
      expression: `(() => {
        const row = document.querySelector('.zv-pdp-rating-row');
        if (!row) return { error: 'Row not found' };
        const rect = row.getBoundingClientRect();
        const children = Array.from(row.children).map(c => {
          const r = c.getBoundingClientRect();
          return { tag: c.tagName, class: c.className, top: r.top, height: r.height };
        });
        const tops = [...new Set(children.map(c => Math.round(c.top)))];
        return {
          width: rect.width,
          height: rect.height,
          tops: tops,
          isSingleLine: tops.length <= 1,
          childrenCount: children.length
        };
      })()`,
      returnByValue: true
    });
    console.log('Desktop rating check:', evalRes.result.value);

    // Capture Desktop screenshot
    const shotDesktop = await send('Page.captureScreenshot', { format: 'png' });
    const deskPath = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_trustpilot_single_line_desktop.png';
    fs.writeFileSync(deskPath, Buffer.from(shotDesktop.data, 'base64'));
    console.log('Saved Desktop screenshot:', deskPath);

    // Mobile 390px
    await send('Emulation.setDeviceMetricsOverride', {
      width: 390,
      height: 844,
      deviceScaleFactor: 2,
      mobile: true
    });
    await new Promise(r => setTimeout(r, 1000));

    const evalMobile = await send('Runtime.evaluate', {
      expression: `(() => {
        const row = document.querySelector('.zv-pdp-rating-row');
        if (!row) return { error: 'Row not found' };
        const rect = row.getBoundingClientRect();
        const children = Array.from(row.children).map(c => {
          const r = c.getBoundingClientRect();
          return { tag: c.tagName, class: c.className, top: r.top, height: r.height };
        });
        const tops = [...new Set(children.map(c => Math.round(c.top)))];
        return {
          width: rect.width,
          height: rect.height,
          tops: tops,
          isSingleLine: tops.length <= 1,
          childrenCount: children.length
        };
      })()`,
      returnByValue: true
    });
    console.log('Mobile 390px rating check:', evalMobile.result.value);

    const shotMobile = await send('Page.captureScreenshot', { format: 'png' });
    const mobilePath = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\qa_trustpilot_single_line_mobile.png';
    fs.writeFileSync(mobilePath, Buffer.from(shotMobile.data, 'base64'));
    console.log('Saved Mobile screenshot:', mobilePath);

    ws.close();
  } catch(e) {
    console.error('Error in QA:', e);
  } finally {
    chromeProcess.kill();
  }
}

run();

