import { adminGraphql } from './config.mjs';
import fs from 'fs';

async function main() {
  const filenames = [
    "sections/zavelyn-v4-pdp-main.liquid",
    "assets/zavelyn-v4-pdp.css",
    "assets/zavelyn-v4-pdp.js",
    "sections/willa-cart-drawer.liquid",
    "sections/trymalora-pdp-how-it-works.liquid",
    "sections/trymalora-pdp-faq.liquid",
    "sections/trymalora-pdp-package.liquid"
  ];
  const query = `
    query {
      theme(id: "gid://shopify/OnlineStoreTheme/197111513459") {
        id
        name
        role
        files(first: 20, filenames: ${JSON.stringify(filenames)}) {
          nodes {
            filename
            updatedAt
            body {
              ... on OnlineStoreThemeFileBodyText {
                content
              }
            }
          }
        }
      }
    }
  `;
  const res = await adminGraphql(query);
  const nodes = res.theme.files.nodes;
  for (const node of nodes) {
    const local = fs.existsSync(node.filename) ? fs.readFileSync(node.filename, 'utf8') : '';
    const remote = node.body?.content || '';
    console.log(`${node.filename}: remote len=${remote.length}, local len=${local.length}, match=${remote === local}`);
  }
}

main();

