const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

const chromePath = 'C:\\\\Program Files\\\\Google\\\\Chrome\\\\Application\\\\chrome.exe';
const userDataDir = 'C:\\\\Users\\\\Admin\\\\.chrome-headless-qa-bottom';

function getWsUrl(port) {
  return new Promise((resolve, reject) => {
    let retries = 0;
    const interval = setInterval(() => {
      http.get(\`http://127.0.0.1:\${port}/json\`, res => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          clearInterval(interval);
          try {
            const tabs = JSON.parse(data);
            const pageTab = tabs.find(t => t.type === 'page') || tabs[0];
            resolve(pageTab.webSocketDebuggerUrl);
          } catch(e) {
            reject(e);
          }
        });
      }).on('error', () => {
        retries++;
        if (retries > 30) {
          clearInterval(interval);
          reject(new Error('Timeout connecting to Chrome CDP'));
        }
      });
    }, 200);
  });
}

async function run() {
  const port = 9345;
  const chromeProcess = spawn(chromePath, [
    '--headless=new',
    \`--remote-debugging-port=\${port}\`,
    \`--user-data-dir=\${userDataDir}\`,
    '--disable-gpu',
    '--no-sandbox',
    '--window-size=1440,1200'
  ]);

  try {
    const wsUrl = await getWsUrl(port);
    const ws = new WebSocket(wsUrl);

    let idSeq = 1;
    function send(method, params = {}) {
      return new Promise(resolve => {
        const id = idSeq++;
        const handler = e => {
          const d = JSON.parse(e.data);
          if (d.id === id) {
            ws.removeEventListener('message', handler);
            resolve(d.result);
          }
        };
        ws.addEventListener('message', handler);
        ws.send(JSON.stringify({ id, method, params }));
      });
    }

    await new Promise(res => ws.addEventListener('open', res));
    await send('Page.enable');
    await send('Runtime.enable');

    await send('Page.navigate', { url: 'https://ikwh1h-fx.myshopify.com/collections/all?preview_theme_id=197144805747' });
    await new Promise(r => setTimeout(r, 4000));

    // Scroll to delivery section
    await send('Runtime.evaluate', {
      expression: \`
        document.querySelectorAll('.shopify-policy-banner, #preview-bar-iframe, iframe[src*=\"preview\"], #shopify-pc__banner').forEach(el => el.remove());
        const del = document.querySelector('.zv-delivery-section');
        if (del) del.scrollIntoView();
      \`
    });
    await new Promise(r => setTimeout(r, 1000));

    const shotBottom = await send('Page.captureScreenshot', { format: 'png' });
    const botPath = 'C:\\\\Users\\\\Admin\\\\.gemini\\\\antigravity\\\\brain\\\\d284d670-0cfd-4f12-bbed-f8eeaea36551\\\\qa_draft_showroom_delivery_footer.png';
    fs.writeFileSync(botPath, Buffer.from(shotBottom.data, 'base64'));
    console.log('Saved Delivery Footer Screenshot to:', botPath);

    ws.close();
  } catch(e) {
    console.error(e);
  } finally {
    chromeProcess.kill();
  }
}

run();
"

