import { adminGraphql, SHOP } from './config.mjs';

async function main() {
  console.log('--- Setting up Variants for Metallic Silver Anti-Rust Renovation Coating ---');

  // 1. Get product details
  const prodRes = await adminGraphql(`{
    productByHandle(handle: "metallic-silver-anti-rust-renovation-coating") {
      id
      title
      handle
      options {
        id
        name
        values
      }
      variants(first: 20) {
        nodes {
          id
          title
          price
          selectedOptions {
            name
            value
          }
        }
      }
    }
  }`);

  const p = prodRes.productByHandle;
  if (!p) {
    throw new Error('Product metallic-silver-anti-rust-renovation-coating not found!');
  }
  console.log(`Product: ${p.title} (${p.id})`);
  console.log('Current options:', p.options);
  console.log('Current variants:', p.variants.nodes);

  // Desired variants:
  // 1: Buy 5 Get 3 FREE (8 Cans Total · 50g) -> $99.95
  // 2: Buy 3 Get 1 FREE (4 Cans Total · 50g) -> $59.97
  // 3: 1 Can (50g Starter Kit) -> $19.99

  const desiredVariants = [
    { title: 'Buy 5 Get 3 FREE (8 Cans Total · 50g)', price: '99.95' },
    { title: 'Buy 3 Get 1 FREE (4 Cans Total · 50g)', price: '59.97' },
    { title: '1 Can (50g Starter Kit)', price: '19.99' }
  ];

  const currentOption = p.options[0];
  if (currentOption.name !== 'Package') {
    console.log(`Updating option name from "${currentOption.name}" to "Package"...`);
    const optRes = await adminGraphql(`
      mutation productOptionUpdate($productId: ID!, $id: ID!, $option: OptionUpdateInput!) {
        productOptionUpdate(productId: $productId, id: $id, option: $option) {
          userErrors { field message }
        }
      }
    `, {
      productId: p.id,
      id: currentOption.id,
      option: { name: 'Package' }
    });
    console.log('Option update:', optRes);
  }

  // Check existing variants
  const existingVariants = p.variants.nodes;
  console.log(`Existing variants count: ${existingVariants.length}`);

  // Update first existing variant to "Buy 5 Get 3 FREE (8 Cans Total · 50g)"
  const firstVariant = existingVariants[0];
  console.log(`Updating first variant ${firstVariant.id} to "${desiredVariants[0].title}" ($${desiredVariants[0].price})...`);
  const updateFirstRes = await adminGraphql(`
    mutation productVariantUpdate($input: ProductVariantInput!) {
      productVariantUpdate(input: $input) {
        productVariant {
          id
          title
          price
        }
        userErrors { field message }
      }
    }
  `, {
    input: {
      id: firstVariant.id,
      price: desiredVariants[0].price,
      compareAtPrice: null,
      options: [desiredVariants[0].title]
    }
  });
  console.log('Update first variant result:', updateFirstRes);

  // If there are other variants, update or delete them or create new ones
  for (let i = 1; i < desiredVariants.length; i++) {
    const target = desiredVariants[i];
    if (existingVariants[i]) {
      // Update existing
      console.log(`Updating variant #${i + 1} (${existingVariants[i].id}) to "${target.title}" ($${target.price})...`);
      const updRes = await adminGraphql(`
        mutation productVariantUpdate($input: ProductVariantInput!) {
          productVariantUpdate(input: $input) {
            productVariant {
              id
              title
              price
            }
            userErrors { field message }
          }
        }
      `, {
        input: {
          id: existingVariants[i].id,
          price: target.price,
          compareAtPrice: null,
          options: [target.title]
        }
      });
      console.log(`Update variant #${i + 1} result:`, updRes);
    } else {
      // Create new variant
      console.log(`Creating new variant "${target.title}" ($${target.price})...`);
      const createRes = await adminGraphql(`
        mutation productVariantCreate($input: ProductVariantInput!) {
          productVariantCreate(input: $input) {
            productVariant {
              id
              title
              price
            }
            userErrors { field message }
          }
        }
      `, {
        input: {
          productId: p.id,
          price: target.price,
          compareAtPrice: null,
          options: [target.title]
        }
      });
      console.log(`Create variant "${target.title}" result:`, createRes);
    }
  }

  // If there are more than 3 variants, delete the excess ones
  if (existingVariants.length > desiredVariants.length) {
    for (let i = desiredVariants.length; i < existingVariants.length; i++) {
      console.log(`Deleting excess variant #${i + 1} (${existingVariants[i].id})...`);
      await adminGraphql(`
        mutation productVariantDelete($id: ID!) {
          productVariantDelete(id: $id) {
            deletedVariantId
            userErrors { field message }
          }
        }
      `, { id: existingVariants[i].id });
    }
  }

  // Fetch final variant list to verify
  const finalRes = await adminGraphql(`{
    productByHandle(handle: "metallic-silver-anti-rust-renovation-coating") {
      variants(first: 10) {
        nodes {
          id
          title
          price
        }
      }
    }
  }`);
  console.log('Final product variants:', JSON.stringify(finalRes.productByHandle.variants.nodes, null, 2));
}

main().catch(console.error);

