  ...dataSrcs,
  ...videoSrcs,
  ...directVideoUrls,
  ...gifUrls,
  ...webpUrls
])].filter(u => u.startsWith('http') && !u.includes('tracking') && !u.includes('analytics') && !u.includes('facebook') && !u.includes('pixel'));

