function sanitizeText(text) {
  // Redact Shopify merchant tokens and shared secrets to prevent GitHub Push Protection blocks
  return text.replace(/shp(at|ca|ss)_[a-zA-Z0-9_-]+/g, (match, type) => `shp${type}_[REDACTED_SECRET_FOR_GITHUB_PUSH]`);
}

async function copyAndSanitizeFile(src, dest) {
  const readStream = fs.createReadStream(src);
  const writeStream = fs.createWriteStream(dest);
  const rl = readline.createInterface({ input: readStream, crlfDelay: Infinity });

  for await (const line of rl) {
