    .replace(/shp(at|ca|ss|va|pa|in)_[a-zA-Z0-9_-]+/g, 'shp_[REDACTED_SHOPIFY_SECRET]')
    .replace(/Cv[A-Za-z0-9_-]{50,}/g, 'Cv_[REDACTED_SHOPIFY_CLI_SESSION]');
