args.Content:
/* ==========================================================================
   ULTRA OVERNIGHT™ — PREMIUM FEMININE DESIGN SYSTEM
   Visual Identity: Luxury Wellness / High-Conversion DTC / Feminine Editorial
   ========================================================================== */

:root {
  --uo-plum: #58233D;
  --uo-plum-dark: #43172C;
  --uo-burgundy: #74304D;
  --uo-dusty-rose: #C98F9D;
  --uo-blush: #F4E4E5;
  --uo-blush-light: #FAF2F2;
  --uo-cream: #FBF7F3;
  --uo-cream-warm: #F7EFE9;
  --uo-muted-mauve: #A67F91;
  --uo-charcoal: #282229;
  --uo-body-text: #4F4349;
  --uo-white: #FFFFFF;
  --uo-border: #EFE3E5;
  --uo-border-light: #F5EAEB;

  --uo-font-serif: 'Playfair Display', 'Cormorant Garamond', 'Didot', Georgia, serif;
  --uo-font-sans: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --uo-radius-sm: 4px;
  --uo-radius-md: 8px;
  --uo-radius-lg: 12px;
  --uo-radius-pill: 9999px;

  --uo-shadow-sm: 0 2px 8px rgba(88, 35, 61, 0.04);
  --uo-shadow-md: 0 4px 20px rgba(88, 35, 61, 0.08);
  --uo-shadow-lg: 0 12px 36px rgba(88, 35, 61, 0.12);

  --uo-max-width: 1240px;
}

/* Base resets & typography for Ultra Overnight scoped components */
.uo-wrap {
  width: 100%;
  max-width: var(--uo-max-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: 20px;
  padding-right: 20px;
  box-sizing: border-box;
}

.uo-heading-serif {
  font-family: var(--uo-font-serif);
  color: var(--uo-plum);
  letter-spacing: -0.01em;
  margin: 0;
  font-weight: 600;
}

.uo-eyebrow {
  font-family: var(--uo-font-sans);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--uo-burgundy);
  margin-bottom: 12px;
  display: block;
}

.uo-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background-color: var(--uo-plum);
  color: var(--uo-white);
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.5px;
  padding: 14px 28px;
  border-radius: var(--uo-radius-sm);
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.2s ease;
}

.uo-btn-primary:hover {
  background-color: var(--uo-plum-dark);
  color: var(--uo-white);
  transform: translateY(-1px);
}

.uo-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: transparent;
  color: var(--uo-plum);
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.5px;
  padding: 13px 26px;
  border-radius: var(--uo-radius-sm);
  text-decoration: none;
  border: 1px solid var(--uo-plum);
  cursor: pointer;
  transition: all 0.2s ease;
}

.uo-btn-secondary:hover {
  background-color: var(--uo-blush);
  color: var(--uo-plum);
}

/* ==========================================================================
   1. ANNOUNCEMENT BAR & HEADER
   ========================================================================== */
.uo-announcement-bar {
  background-color: var(--uo-plum);
  color: var(--uo-white);
  font-family: var(--uo-font-sans);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.6px;
  text-align: center;
  padding: 8px 16px;
  line-height: 1.4;
}

.uo-announcement-bar span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.uo-header-wrap {
  background-color: var(--uo-white);
  border-bottom: 1px solid var(--uo-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.uo-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.uo-logo {
  display: flex;
  align-items: center;
  text-decoration: none;
}

.uo-logo svg {
  height: 38px;
  width: auto;
}

.uo-nav {
  display: flex;
  align-items: center;
  gap: 36px;
}

.uo-nav-link {
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 500;
  color: var(--uo-charcoal);
  text-decoration: none;
  position: relative;
  padding: 6px 0;
  transition: color 0.2s ease;
}

.uo-nav-link:hover,
.uo-nav-link.is-active {
  color: var(--uo-plum);
}

.uo-nav-link.is-active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: var(--uo-plum);
}

.uo-header-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.uo-header-icon-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  color: var(--uo-charcoal);
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  position: relative;
  transition: color 0.2s ease;
}

.uo-header-icon-btn:hover {
  color: var(--uo-plum);
}

.uo-cart-badge {
  position: absolute;
  top: 0;
  right: -2px;
  background-color: var(--uo-plum);
  color: var(--uo-white);
  font-size: 10px;
  font-weight: 700;
  height: 16px;
  min-width: 16px;
  padding: 0 4px;
  border-radius: var(--uo-radius-pill);
  display: flex;
  align-items: center;
  justify-content: center;
}

.uo-mobile-menu-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  color: var(--uo-plum);
}

/* Mobile Drawer */
.uo-mobile-drawer {
  position: fixed;
  top: 0;
  left: 0;
  width: 290px;
  height: 100vh;
  background-color: var(--uo-white);
  z-index: 1001;
  transform: translateX(-100%);
  transition: transform 0.3s ease;
  box-shadow: 4px 0 24px rgba(0,0,0,0.15);
  display: flex;
  flex-direction: column;
}

.uo-mobile-drawer.is-open {
  transform: translateX(0);
}

.uo-mobile-drawer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: rgba(40, 34, 41, 0.4);
  z-index: 1000;
  display: none;
}

.uo-mobile-drawer-overlay.is-open {
  display: block;
}

.uo-mobile-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px;
  border-bottom: 1px solid var(--uo-border);
}

.uo-mobile-nav {
  display: flex;
  flex-direction: column;
  padding: 24px 20px;
  gap: 20px;
}

.uo-mobile-nav-link {
  font-family: var(--uo-font-sans);
  font-size: 16px;
  font-weight: 600;
  color: var(--uo-charcoal);
  text-decoration: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.uo-mobile-nav-link:hover {
  color: var(--uo-plum);
}

/* ==========================================================================
   2. HERO SECTION
   ========================================================================== */
.uo-hero-section {
  background: linear-gradient(180deg, #FDF9F7 0%, #F9ECEE 100%);
  padding: 48px 0 64px 0;
  position: relative;
  overflow: hidden;
}

.uo-hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 40px;
  align-items: center;
}

.uo-hero-content {
  padding-right: 20px;
}

.uo-hero-title {
  font-size: clamp(32px, 3.8vw, 50px);
  line-height: 1.15;
  margin-bottom: 20px;
  font-weight: 600;
}

.uo-hero-desc {
  font-family: var(--uo-font-sans);
  font-size: 16px;
  line-height: 1.65;
  color: var(--uo-body-text);
  margin-bottom: 32px;
  max-width: 520px;
}

.uo-hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.uo-hero-media-wrap {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.uo-hero-media {
  width: 100%;
  max-width: 520px;
  height: auto;
  border-radius: var(--uo-radius-lg);
  box-shadow: var(--uo-shadow-lg);
  object-fit: cover;
  display: block;
}

/* ==========================================================================
   3. BENEFIT STRIP
   ========================================================================== */
.uo-benefit-strip {
  background-color: var(--uo-white);
  border-top: 1px solid var(--uo-border);
  border-bottom: 1px solid var(--uo-border);
  padding: 24px 0;
}

.uo-benefit-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  align-items: center;
}

.uo-benefit-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  border-right: 1px solid var(--uo-border);
  padding: 4px 16px;
}

.uo-benefit-item:last-child {
  border-right: none;
}

.uo-benefit-icon {
  width: 28px;
  height: 28px;
  color: var(--uo-plum);
  flex-shrink: 0;
}

.uo-benefit-text {
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 600;
  color: var(--uo-charcoal);
  line-height: 1.25;
}

/* ==========================================================================
   4. SEVEN PILLARS SECTION
   ========================================================================== */
.uo-pillars-section {
  background-color: var(--uo-cream);
  padding: 72px 0;
  text-align: center;
}

.uo-pillars-header {
  max-width: 680px;
  margin: 0 auto 48px auto;
}

.uo-pillars-title {
  font-size: clamp(26px, 3vw, 36px);
  margin-bottom: 12px;
}

.uo-pillars-subhead {
  font-family: var(--uo-font-sans);
  font-size: 15px;
  color: var(--uo-body-text);
  line-height: 1.5;
  margin: 0;
}

.uo-pillars-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 12px;
}

.uo-pillar-card {
  background-color: var(--uo-white);
  border: 1px solid var(--uo-border);
  border-radius: var(--uo-radius-md);
  padding: 24px 12px 20px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  box-shadow: var(--uo-shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.uo-pillar-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--uo-shadow-md);
}

.uo-pillar-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: var(--uo-radius-pill);
  background-color: var(--uo-blush);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--uo-plum);
  margin-bottom: 14px;
}

.uo-pillar-icon-wrap svg {
  width: 22px;
  height: 22px;
}

.uo-pillar-name {
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 700;
  color: var(--uo-plum);
  margin-bottom: 8px;
}

.uo-pillar-desc {
  font-family: var(--uo-font-sans);
  font-size: 12px;
  color: var(--uo-body-text);
  line-height: 1.45;
  margin: 0;
}

/* ==========================================================================
   5. FIVE LAYERS EXPLODED SECTION
   ========================================================================== */
.uo-layers-section {
  background-color: #FAF2F2;
  padding: 80px 0;
  border-top: 1px solid var(--uo-border);
  border-bottom: 1px solid var(--uo-border);
}

.uo-layers-grid {
  display: grid;
  grid-template-columns: 1fr 1.15fr 1fr;
  gap: 32px;
  align-items: center;
}

.uo-layers-visual-left {
  text-align: center;
}

.uo-layers-visual-left img {
  max-width: 100%;
  height: auto;
  border-radius: var(--uo-radius-md);
}

.uo-layers-center-text {
  text-align: left;
  padding: 0 10px;
}

.uo-layers-title {
  font-size: clamp(28px, 3.2vw, 42px);
  line-height: 1.18;
  margin-bottom: 16px;
}

.uo-layers-desc {
  font-family: var(--uo-font-sans);
  font-size: 15px;
  color: var(--uo-body-text);
  line-height: 1.6;
  margin: 0;
}

.uo-layers-list-right {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.uo-layer-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.uo-layer-badge {
  width: 24px;
  height: 24px;
  border-radius: var(--uo-radius-pill);
  background-color: var(--uo-plum);
  color: var(--uo-white);
  font-family: var(--uo-font-sans);
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 2px;
}

.uo-layer-info h4 {
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 700;
  color: var(--uo-charcoal);
  margin: 0 0 3px 0;
}

.uo-layer-info p {
  font-family: var(--uo-font-sans);
  font-size: 12.5px;
  color: var(--uo-body-text);
  line-height: 1.4;
  margin: 0;
}

/* ==========================================================================
   6. LIFESTYLE COMFORT SECTION
   ========================================================================== */
.uo-comfort-section {
  background-color: var(--uo-white);
  padding: 72px 0;
}

.uo-comfort-grid {
  display: grid;
  grid-template-columns: 1fr 2.6fr;
  gap: 40px;
  align-items: center;
}

.uo-comfort-intro h2 {
  font-size: clamp(28px, 3.2vw, 38px);
  line-height: 1.2;
  margin-bottom: 16px;
}

.uo-comfort-intro p {
  font-family: var(--uo-font-sans);
  font-size: 15px;
  color: var(--uo-body-text);
  line-height: 1.6;
  margin: 0;
}

.uo-comfort-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.uo-comfort-card {
  position: relative;
  border-radius: var(--uo-radius-md);
  overflow: hidden;
  height: 240px;
  box-shadow: var(--uo-shadow-sm);
  display: flex;
  align-items: flex-end;
}

.uo-comfort-card img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.uo-comfort-card:hover img {
  transform: scale(1.04);
}

.uo-comfort-card-overlay {
  position: relative;
  width: 100%;
  padding: 20px 16px;
  background: linear-gradient(180deg, rgba(88,35,61,0) 0%, rgba(88,35,61,0.85) 60%, rgba(88,35,61,0.95) 100%);
  color: var(--uo-white);
  box-sizing: border-box;
}

.uo-comfort-card-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 700;
  color: var(--uo-white);
  margin-bottom: 6px;
}

.uo-comfort-card-desc {
  font-family: var(--uo-font-sans);
  font-size: 12px;
  line-height: 1.4;
  color: var(--uo-blush);
  margin: 0;
}

/* ==========================================================================
   7. REVIEWS SECTION
   ========================================================================== */
.uo-reviews-section {
  background-color: var(--uo-cream);
  padding: 72px 0;
  border-top: 1px solid var(--uo-border);
}

.uo-reviews-grid {
  display: grid;
  grid-template-columns: 1fr 2.6fr;
  gap: 40px;
  align-items: center;
}

.uo-reviews-intro h2 {
  font-size: clamp(26px, 3vw, 36px);
  margin-bottom: 12px;
}

.uo-star-row {
  display: flex;
  align-items: center;
  gap: 4px;
  color: #D97706;
  font-size: 16px;
  margin-bottom: 12px;
}

.uo-reviews-intro p {
  font-family: var(--uo-font-sans);
  font-size: 14px;
  color: var(--uo-body-text);
  line-height: 1.5;
  margin: 0;
}

.uo-reviews-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.uo-review-card {
  background-color: var(--uo-white);
  border: 1px solid var(--uo-border);
  border-radius: var(--uo-radius-md);
  padding: 24px 20px;
  box-shadow: var(--uo-shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.uo-review-stars {
  color: #D97706;
  font-size: 14px;
  margin-bottom: 10px;
}

.uo-review-quote {
  font-family: var(--uo-font-sans);
  font-size: 13.5px;
  font-weight: 700;
  color: var(--uo-charcoal);
  margin-bottom: 8px;
}

.uo-review-body {
  font-family: var(--uo-font-sans);
  font-size: 12.5px;
  color: var(--uo-body-text);
  line-height: 1.5;
  margin-bottom: 18px;
}

.uo-reviewer-info {
  display: flex;
  align-items: center;
  gap: 10px;
}

.uo-reviewer-avatar {
  width: 32px;
  height: 32px;
  border-radius: var(--uo-radius-pill);
  object-fit: cover;
}

.uo-reviewer-meta {
  font-family: var(--uo-font-sans);
}

.uo-reviewer-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--uo-charcoal);
  display: block;
}

.uo-reviewer-badge {
  font-size: 11px;
  color: #059669;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ==========================================================================
   8. FAQ SECTION
   ========================================================================== */
.uo-faq-section {
  background-color: var(--uo-white);
  padding: 72px 0 84px 0;
}

.uo-faq-title {
  font-size: clamp(26px, 3vw, 36px);
  margin-bottom: 36px;
  text-align: left;
}

.uo-faq-list {
  max-width: 900px;
  display: flex;
  flex-direction: column;
}

.uo-faq-item {
  border-bottom: 1px solid var(--uo-border);
}

.uo-faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 0;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--uo-font-sans);
  font-size: 16px;
  font-weight: 600;
  color: var(--uo-charcoal);
  transition: color 0.2s ease;
}

.uo-faq-trigger:hover {
  color: var(--uo-plum);
}

.uo-faq-icon {
  font-size: 20px;
  color: var(--uo-plum);
  font-weight: 400;
  transition: transform 0.25s ease;
}

.uo-faq-item.is-active .uo-faq-icon {
  transform: rotate(45deg);
}

.uo-faq-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s cubic-bezier(0, 1, 0, 1);
}

.uo-faq-item.is-active .uo-faq-content {
  max-height: 400px;
  transition: max-height 0.3s ease-in-out;
}

.uo-faq-body {
  padding-bottom: 22px;
  font-family: var(--uo-font-sans);
  font-size: 14.5px;
  line-height: 1.65;
  color: var(--uo-body-text);
}

/* ==========================================================================
   9. FOOTER
   ========================================================================== */
.uo-footer {
  background-color: var(--uo-plum);
  color: var(--uo-white);
  padding: 64px 0 32px 0;
}

.uo-footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr 1.6fr;
  gap: 36px;
  margin-bottom: 48px;
}

.uo-footer-brand p {
  font-family: var(--uo-font-sans);
  font-size: 13.5px;
  color: var(--uo-blush);
  margin-top: 14px;
  line-height: 1.5;
}

.uo-footer-col h4 {
  font-family: var(--uo-font-sans);
  font-size: 14px;
  font-weight: 700;
  color: var(--uo-white);
  margin: 0 0 18px 0;
  letter-spacing: 0.5px;
}

.uo-footer-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.uo-footer-col a {
  font-family: var(--uo-font-sans);
  font-size: 13.5px;
  color: var(--uo-blush);
  text-decoration: none;
  transition: color 0.2s ease;
}

.uo-footer-col a:hover {
  color: var(--uo-white);
}

.uo-newsletter-text {
  font-family: var(--uo-font-sans);
  font-size: 13.5px;
  color: var(--uo-blush);
  margin-bottom: 14px;
  line-height: 1.45;
}

.uo-newsletter-form {
  display: flex;
  align-items: center;
  background-color: var(--uo-white);
  border-radius: var(--uo-radius-sm);
  padding: 3px;
  margin-bottom: 16px;
}

.uo-newsletter-input {
  flex: 1;
  border: none;
  background: transparent;
  padding: 10px 14px;
  font-family: var(--uo-font-sans);
  font-size: 13px;
  color: var(--uo-charcoal);
  outline: none;
}

.uo-newsletter-btn {
