const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');
const path = require('path');

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const userDataDir = 'C:\\Users\\Admin\\.chrome-headless-qa-ultra';
const artifactsDir = 'C:\\Users\\Admin\\.gemini\\antigravity\\brain\\d284d670-0cfd-4f12-bbed-f8eeaea36551';
const DRAFT_THEME_ID = '[SHOPIFY_THEME_ID_REDACTED]';
const DOMAIN = 'ikwh1h-fx.myshopify.com';

function getWsUrl(port) {
  return new Promise((resolve, reject) => {
    let retries = 0;
    const interval = setInterval(() => {
      http.get('http://127.0.0.1:' + port + '/json', res => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          clearInterval(interval);
          try {
            const tabs = JSON.parse(data);
            resolve((tabs.find(t => t.type === 'page') || tabs[0]).webSocketDebuggerUrl);
          } catch(e) {
            reject(e);
          }
        });
      }).on('error', () => { if (++retries > 30) reject(); });
    }, 200);
  });
}

(async () => {
  const port = 9415;
  const p = spawn(chromePath, [
    '--headless=new',
    '--remote-debugging-port=' + port,
    '--user-data-dir=' + userDataDir,
    '--window-size=1440,1100'
  ]);

  const ws = new WebSocket(await getWsUrl(port));
  let id = 1;
  function send(m, params = {}) {
    return new Promise(r => {
      const curId = id++;
      const h = e => {
        const d = JSON.parse(e.data);
        if (d.id === curId) {
          ws.removeEventListener('message', h);
          r(d.result);
        }
      };
      ws.addEventListener('message', h);
      ws.send(JSON.stringify({ id: curId, method: m, params }));
    });
  }

  await new Promise(r => ws.addEventListener('open', r, { once: true }));
  await send('Page.enable');
  await send('Runtime.enable');

  async function takeCleanScreenshot(filename) {
    await send('Runtime.evaluate', {
      expression: `
        (() => {
          const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim().toLowerCase() === 'accept');
          if (btn) btn.click();
          const modal = document.querySelector('.shopify-pc__banner, [aria-label*="cookie" i]');
          if (modal) modal.remove();
        })()
      `
    });
    await new Promise(r => setTimeout(r, 600));
    const res = await send('Page.captureScreenshot', { format: 'png' });
    if (res && res.data) {
      const buf = Buffer.from(res.data, 'base64');
      const artPath = path.join(artifactsDir, filename);
      fs.writeFileSync(artPath, buf);
      console.log(`  [SAVED] ${filename} (${(buf.length / 1024).toFixed(1)} KB)`);
    }
  }

  // Set password & preview cookie
  await send('Page.navigate', { url: `https://${DOMAIN}/?preview_theme_id=${DRAFT_THEME_ID}` });
  await new Promise(r => setTimeout(r, 3000));
  await send('Runtime.evaluate', {
    expression: `
      const pw = document.querySelector('input[type="password"]');
      if (pw) { pw.value = '[STOREFRONT_PASSWORD_REDACTED]'; const f = pw.closest('form'); if (f) f.submit(); }
    `
  });
  await new Promise(r => setTimeout(r, 3000));

  // 1. About Us with view=about-us
  console.log('Testing About Us template (?view=about-us)...');
  await send('Page.navigate', { url: `https://${DOMAIN}/pages/contact?view=about-us&preview_theme_id=${DRAFT_THEME_ID}` });
  await new Promise(r => setTimeout(r, 3500));
  const aboutCheck = await send('Runtime.evaluate', {
    expression: `
      (() => ({
        heroTitle: document.querySelector('.uo-page-hero-title')?.textContent?.trim(),
        hasStoryGrid: document.querySelector('.uo-about-grid') !== null
      }))()
    `,
    returnByValue: true
  });
  console.log('About Us View check:', aboutCheck.result.value);
  await takeCleanScreenshot('qa_ultra_about_us.png');

  // 2. Track Order with view=track-order
  console.log('Testing Track Order template (?view=track-order)...');
  await send('Page.navigate', { url: `https://${DOMAIN}/pages/contact?view=track-order&preview_theme_id=${DRAFT_THEME_ID}` });
  await new Promise(r => setTimeout(r, 3500));
  const trackCheck = await send('Runtime.evaluate', {
    expression: `
      (() => ({
        heroTitle: document.querySelector('.uo-page-hero-title')?.textContent?.trim(),
        hasTrackForm: document.querySelector('.uo-track-form') !== null
      }))()
    `,
    returnByValue: true
  });
  console.log('Track Order View check:', trackCheck.result.value);
  await takeCleanScreenshot('qa_ultra_track_order.png');

  // 3. Contact with view=contact
  console.log('Testing Contact template (?view=contact)...');
  await send('Page.navigate', { url: `https://${DOMAIN}/pages/contact?preview_theme_id=${DRAFT_THEME_ID}` });
  await new Promise(r => setTimeout(r, 3500));
  const contactCheck = await send('Runtime.evaluate', {
    expression: `
      (() => ({
        heroTitle: document.querySelector('.uo-page-hero-title')?.textContent?.trim(),
        hasForm: document.querySelector('.uo-track-form') !== null
      }))()
    `,
    returnByValue: true
  });
  console.log('Contact View check:', contactCheck.result.value);
  await takeCleanScreenshot('qa_ultra_contact.png');

  p.kill();
  process.exit(0);
})().catch(e => { console.error(e); process.exit(1); });

